#include <cstring>
#include <stdexcept>
#include <filesystem>
#include <phsint.hpp>
#include "metadata.h"
// Section IDs — must match BytecodeSerializer.cpp
const Phasor::u8 SECTION_CONSTANTS    = 0x01;
const Phasor::u8 SECTION_VARIABLES    = 0x02;
const Phasor::u8 SECTION_INSTRUCTIONS = 0x03;
const Phasor::u8 SECTION_FUNCTIONS    = 0x04;
const Phasor::u8 SECTION_STRUCTS      = 0x05;
const Phasor::u8 SECTION_FUNC_TYPES   = 0x06;
const Phasor::u8 SECTION_SCOPE_VARS   = 0x07;
static Phasor::u32 crc32_table[256];
static bool        crc32_table_initialized = false;
void init_crc32_table_deserializer()
{
	for (Phasor::u32 i = 0; i < 256; i++)
	{
		Phasor::u32 crc = i;
		for (int j = 0; j < 8; j++)
		{
			if ((crc & 1) != 0U)
			{
				crc = (crc >> 1) ^ 0xEDB88320;
			} else {
				crc >>= 1;
			}
		}
		crc32_table[i] = crc;
	}
	crc32_table_initialized = true;
}
namespace Phasor
{
u32 BytecodeDeserializer::calculateCRC32(const u8 *data, size_t size)
{
	if (!crc32_table_initialized)
	{
		init_crc32_table_deserializer();
	}
	u32 crc = 0xFFFFFFFF;
	for (size_t i = 0; i < size; i++)
	{
		crc = (crc >> 8) ^ crc32_table[(crc ^ data[i]) & 0xFF];
	}
	return crc ^ 0xFFFFFFFF;
}
// ---------------------------------------------------------------------------
// Primitive readers
// ---------------------------------------------------------------------------
u8 BytecodeDeserializer::readUInt8()
{
	if (position >= dataSize)
	{
		throw std::runtime_error("Unexpected end of bytecode data");
	}
	return _data[position++];
}
u16 BytecodeDeserializer::readUInt16()
{
	u16 value = 0;
	value |= static_cast<u16>(readUInt8());
	value |= static_cast<u16>(readUInt8()) << 8;
	return value;
}
u32 BytecodeDeserializer::readUInt32()
{
	u32 value = 0;
	value |= static_cast<u32>(readUInt8());
	value |= static_cast<u32>(readUInt8()) << 8;
	value |= static_cast<u32>(readUInt8()) << 16;
	value |= static_cast<u32>(readUInt8()) << 24;
	return value;
}
i32 BytecodeDeserializer::readInt32()
{
	return static_cast<i32>(readUInt32());
}
i64 BytecodeDeserializer::readInt64()
{
	i64 value = 0;
	for (int i = 0; i < 8; i++)
	{
		value |= static_cast<i64>(readUInt8()) << (i * 8);
	}
	return value;
}
f64 BytecodeDeserializer::readDouble()
{
	u64 bits = 0;
	for (int i = 0; i < 8; i++)
	{
		bits |= static_cast<u64>(readUInt8()) << (i * 8);
	}
	f64 value;
	std::memcpy(&value, &bits, sizeof(f64));
	return value;
}
std::string BytecodeDeserializer::readString()
{
	u16         length = readUInt16();
	std::string str;
	str.reserve(length);
	for (u16 i = 0; i < length; i++)
	{
		str.push_back(static_cast<char>(readUInt8()));
	}
	return str;
}
// ---------------------------------------------------------------------------
// Recursive value reader — mirrors BytecodeSerializer::writeValue exactly.
// ---------------------------------------------------------------------------
Value BytecodeDeserializer::readValue()
{
	u8 typeTag = readUInt8();
	switch (typeTag)
	{
	case 0: // Null
		return Value{};
	case 1: // Bool
		return Value{readUInt8() != 0};
	case 2: // Int
		return Value{readInt64()};
	case 3: // Float
		return Value{readDouble()};
	case 4: // String
		return Value{readString()};
	case 5: // Struct
	{
		std::string typeName   = readString();
		u32         fieldCount = readUInt32();
		Value structVal = Value::createStruct(PhsString(typeName));
		for (u32 i = 0; i < fieldCount; ++i)
		{
			std::string fieldName = readString();
			Value       fieldVal  = readValue(); // recurse
			structVal.setField(PhsString(fieldName), std::move(fieldVal));
		}
		return structVal;
	}
	case 6: // Array
	{
		u32                elementCount = readUInt32();
		std::vector<Value> elements;
		elements.reserve(elementCount);
		for (u32 i = 0; i < elementCount; ++i)
		{
			elements.push_back(readValue()); // recurse
		}
		return Value::createArray(std::move(elements));
	}
	default:
		throw std::runtime_error("BytecodeDeserializer::readValue: unknown type tag " +
		                         std::to_string(typeTag));
	}
}
// ---------------------------------------------------------------------------
// Section readers
// ---------------------------------------------------------------------------
void BytecodeDeserializer::readHeader(u32 &checksum)
{
	u32 magic = readUInt32();
	if (magic != MAGIC_NUMBER)
	{
		throw std::runtime_error("Invalid bytecode file: incorrect magic number");
	}
	u32 version = readUInt32();
	if (version != VERSION)
	{
		throw std::runtime_error("Incompatible bytecode version");
	}
	u32 flags = readUInt32(); // Reserved
	(void)flags;
	checksum = readUInt32();
}
void BytecodeDeserializer::readConstantPool(Bytecode &bytecode)
{
	u8 sectionId = readUInt8();
	if (sectionId != SECTION_CONSTANTS)
	{
		throw std::runtime_error("Expected constant pool section");
	}
	u32 count = readUInt32();
	bytecode.constants.reserve(count);
	for (u32 i = 0; i < count; i++)
	{
		bytecode.constants.push_back(readValue());
	}
}
void BytecodeDeserializer::readVariableMapping(Bytecode &bytecode)
{
	u8 sectionId = readUInt8();
	if (sectionId != SECTION_VARIABLES)
	{
		throw std::runtime_error("Expected variable mapping section");
	}
	u32 count = readUInt32();
	bytecode.nextVarIndex = readInt32();
	for (u32 i = 0; i < count; i++)
	{
		std::string name  = readString();
		i32         index = readInt32();
		bytecode.variables[name] = index;
	}
}
void BytecodeDeserializer::readInstructions(Bytecode &bytecode)
{
	u8 sectionId = readUInt8();
	if (sectionId != SECTION_INSTRUCTIONS)
	{
		throw std::runtime_error("Expected instructions section");
	}
	u32 count = readUInt32();
	bytecode.instructions.reserve(count);
	for (u32 i = 0; i < count; i++)
	{
		u8  opcode = readUInt8();
		i32 op1    = readInt32();
		i32 op2    = readInt32();
		i32 op3    = readInt32();
		bytecode.instructions.emplace_back(static_cast<OpCode>(opcode), op1, op2, op3);
	}
}
void BytecodeDeserializer::readFunctionEntries(Bytecode &bytecode)
{
	u8 sectionId = readUInt8();
	if (sectionId != SECTION_FUNCTIONS) 
	{
		throw std::runtime_error("Expected function entries section");
	}
	u32 count = readUInt32();
	for (u32 i = 0; i < count; i++)
	{
		std::string name    = readString();
		i32         address = readInt32();
		bytecode.functionEntries[name] = address;
	}
}
/**
 * @brief Read function type signatures section (0x06).
 *
 * Reconstructs bytecode.functionParamTypeNames, bytecode.functionReturnTypeNames,
 * and bytecode.functionParamCounts.
 */
void BytecodeDeserializer::readFunctionTypes(Bytecode &bytecode)
{
	u8 sectionId = readUInt8();
	if (sectionId != SECTION_FUNC_TYPES)
	{
		throw std::runtime_error("Expected function type signatures section");
	}
	u32 count = readUInt32();
	for (u32 i = 0; i < count; i++)
	{
		std::string name           = readString();
		std::string returnTypeName = readString();
		u32         paramCount     = readUInt32();
		std::vector<std::string> paramTypes;
		paramTypes.reserve(paramCount);
		for (u32 p = 0; p < paramCount; p++)
		{
			paramTypes.push_back(readString());
		}
		bytecode.functionParamTypeNames[name]  = std::move(paramTypes);
		bytecode.functionReturnTypeNames[name]  = std::move(returnTypeName);
		bytecode.functionParamCounts[name]      = static_cast<int>(paramCount);
	}
}
/**
 * @brief Read struct type definitions section (0x05).
 *
 * Reconstructs bytecode.structs and bytecode.structEntries.
 */
void BytecodeDeserializer::readStructSection(Bytecode &bytecode)
{
	u8 sectionId = readUInt8();
	if (sectionId != SECTION_STRUCTS)
	{
		throw std::runtime_error("Expected struct definitions section");
	}
	u32 structCount = readUInt32();
	bytecode.structs.reserve(structCount);
	for (u32 i = 0; i < structCount; i++)
	{
		StructInfo info;
		info.name            = readString();
		info.firstConstIndex = readInt32();
		info.fieldCount      = readInt32();
		info.fieldNames.reserve(static_cast<size_t>(info.fieldCount));
		for (int f = 0; f < info.fieldCount; f++)
		{
			info.fieldNames.push_back(readString());
		}		
		int index = static_cast<int>(bytecode.structs.size());
		bytecode.structs.push_back(std::move(info));
		bytecode.structEntries[bytecode.structs.back().name] = index;
	}
}
/**
 * @brief Read scope variable lists section (0x07).
 * 
 * Reconstructs bytecode.scopeVarLists.
 */
void BytecodeDeserializer::readScopeVars(Bytecode &bytecode)
{
    u8 sectionId = readUInt8();
    if (sectionId != SECTION_SCOPE_VARS)
	{
        throw std::runtime_error("Expected scope vars section");
	}
    u32 count = readUInt32();
    bytecode.scopeVarLists.resize(count);
    for (u32 i = 0; i < count; i++)
    {
        u32 listSize = readUInt32();
        bytecode.scopeVarLists[i].reserve(listSize);
        for (u32 j = 0; j < listSize; j++)
        {
            int         idx  = readInt32();
            std::string name = readString();
            bytecode.scopeVarLists[i].emplace_back(idx, name);
        }
    }
}
// ---------------------------------------------------------------------------
// Top-level deserialize / loadFromFile
// ---------------------------------------------------------------------------
Bytecode BytecodeDeserializer::deserialize(const std::vector<u8> &buffer)
{
	_data    = buffer.data();
	dataSize = buffer.size();
	position = 0;
	Bytecode bytecode;
	u32 expectedChecksum;
	readHeader(expectedChecksum);
	size_t dataStart      = position;
	u32    actualChecksum = calculateCRC32(_data + dataStart, dataSize - dataStart);
	if (actualChecksum != expectedChecksum)
	{
		throw std::runtime_error("Bytecode file corrupted: checksum mismatch");
	}
	// Sections must be read in the same order they were written.
	readConstantPool(bytecode);
	readVariableMapping(bytecode);
	readScopeVars(bytecode);
	readFunctionEntries(bytecode);
	readFunctionTypes(bytecode);
	readStructSection(bytecode);
	readInstructions(bytecode);
	return bytecode;
}
Bytecode BytecodeDeserializer::loadFromFile(const std::filesystem::path &filename)
{
	std::ifstream file(filename, std::ios::binary | std::ios::ate);
	if (!file.is_open())
	{
		throw std::runtime_error("Failed to open bytecode file: " + filename.string());
	}
	std::streamsize size = file.tellg();
	file.seekg(0, std::ios::beg);
	std::vector<u8> fileBuffer(size);
	if (!file.read(reinterpret_cast<char *>(fileBuffer.data()), size))
	{
		throw std::runtime_error("Failed to read bytecode file: " + filename.string());
	}
	return deserialize(fileBuffer);
}
} // namespace Phasor#pragma once
#include "../Bytecode.hpp"
#include <cstdint>
#include <fstream>
#include <string>
#include <vector>
#include <filesystem>
#include <phsint.hpp>
/// @brief The Phasor Programming Language and Runtime
namespace Phasor
{
/**
 *  @class BytecodeDeserializer
 *  @brief Bytecode binary format deserializer
 */
class BytecodeDeserializer
{
  public:
	/// @brief Deserialize bytecode from binary buffer
	Bytecode deserialize(const std::vector<u8> &data);
	/// @brief Load bytecode from .phsb file
	Bytecode loadFromFile(const std::filesystem::path &filename);
  private:
	const u8 *_data;
	size_t    position;
	size_t    dataSize;
	u8          readUInt8();  ///< Helper method to read UInt8
	u16         readUInt16(); ///< Helper method to read UInt16
	u32         readUInt32(); ///< Helper method to read UInt32
	i32         readInt32();  ///< Helper method to read Int32
	i64         readInt64();  ///< Helper method to read Int64
	f64         readDouble(); ///< Helper method to read Double
	std::string readString(); ///< Helper method to read String
	/// @brief Read a single Value (recursive — handles nested structs/arrays)
	Value readValue();
	void readHeader(u32 &checksum);               ///< Helper method to read Header
	void readConstantPool(Bytecode &bytecode);    ///< Helper method to read Constants Table
	void readVariableMapping(Bytecode &bytecode); ///< Helper method to read Variable Table
	void readInstructions(Bytecode &bytecode);    ///< Helper method to read Instructions Table
	void readFunctionEntries(Bytecode &bytecode); ///< Helper method to read Function Entries
	void readFunctionTypes(Bytecode &bytecode);   ///< Helper method to read Function Type Table
	void readStructSection(Bytecode &bytecode);   ///< Helper method to read Struct Section
	void readScopeVars(Bytecode &bytecode);       ///< Helper method to read Scope Vars
	/// @brief Calculate CRC32 checksum
	static u32 calculateCRC32(const u8 *data, size_t size);
};
} // namespace Phasor#include "BytecodeSerializer.hpp"
#include <cstring>
#include <stdexcept>
#include <filesystem>
#include <fstream>
#include "metadata.h"
#include <phsint.hpp>
// Section IDs
const Phasor::u8 SECTION_CONSTANTS    = 0x01;
const Phasor::u8 SECTION_VARIABLES    = 0x02;
const Phasor::u8 SECTION_INSTRUCTIONS = 0x03;
const Phasor::u8 SECTION_FUNCTIONS    = 0x04;
const Phasor::u8 SECTION_STRUCTS      = 0x05;
const Phasor::u8 SECTION_FUNC_TYPES   = 0x06;
const Phasor::u8 SECTION_SCOPE_VARS   = 0x07;
static Phasor::u32 crc32_table[256];
static bool        crc32_table_initialized = false;
void init_crc32_table()
{
	for (Phasor::u32 i = 0; i < 256; i++)
	{
		Phasor::u32 crc = i;
		for (int j = 0; j < 8; j++)
		{
			if ((crc & 1) != 0U)
			{
				crc = (crc >> 1) ^ 0xEDB88320;
			} else {
				crc >>= 1;
			}
		}
		crc32_table[i] = crc;
	}
	crc32_table_initialized = true;
}
namespace Phasor
{
u32 BytecodeSerializer::calculateCRC32(const std::vector<u8> &data)
{
	if (!crc32_table_initialized)
	{
		init_crc32_table();
	}
	u32 crc = 0xFFFFFFFF;
	for (u8 byte : data)
	{
		crc = (crc >> 8) ^ crc32_table[(crc ^ byte) & 0xFF];
	}
	return crc ^ 0xFFFFFFFF;
}
// ---------------------------------------------------------------------------
// Primitive writers
// ---------------------------------------------------------------------------
void BytecodeSerializer::writeUInt8(u8 value)
{
	buffer.push_back(value);
}
void BytecodeSerializer::writeUInt16(u16 value)
{
	buffer.push_back(static_cast<u8>(value & 0xFF));
	buffer.push_back(static_cast<u8>((value >> 8) & 0xFF));
}
void BytecodeSerializer::writeUInt32(u32 value)
{
	buffer.push_back(static_cast<u8>(value & 0xFF));
	buffer.push_back(static_cast<u8>((value >> 8) & 0xFF));
	buffer.push_back(static_cast<u8>((value >> 16) & 0xFF));
	buffer.push_back(static_cast<u8>((value >> 24) & 0xFF));
}
void BytecodeSerializer::writeInt32(i32 value)
{
	writeUInt32(static_cast<u32>(value));
}
void BytecodeSerializer::writeInt64(i64 value)
{
	for (int i = 0; i < 8; i++)
	{
		buffer.push_back(static_cast<u8>((value >> (i * 8)) & 0xFF));
	}
}
void BytecodeSerializer::writeDouble(f64 value)
{
	u64 bits;
	std::memcpy(&bits, &value, sizeof(f64));
	for (int i = 0; i < 8; i++)
	{
		buffer.push_back(static_cast<u8>((bits >> (i * 8)) & 0xFF));
	}
}
void BytecodeSerializer::writeString(const PhsString &str)
{
	writeUInt16(static_cast<u16>(str.length()));
	for (char c : str)
	{
		buffer.push_back(static_cast<u8>(c));
	}
}
// ---------------------------------------------------------------------------
// Recursive value writer
//
// Binary layout per value:
//   Null   : u8(0)
//   Bool   : u8(1)  u8(0|1)
//   Int    : u8(2)  i64
//   Float  : u8(3)  f64
//   String : u8(4)  u16(len) chars...
//   Struct : u8(5)  string(structName) u32(fieldCount) [string(fieldName) value]...
//   Array  : u8(6)  u32(elementCount) [value]...
// ---------------------------------------------------------------------------
void BytecodeSerializer::writeValue(const Value &val)
{
	switch (val.getType())
	{
	case ValueType::Null:
		writeUInt8(0);
		break;
	case ValueType::Bool:
		writeUInt8(1);
		writeUInt8(val.asBool() ? 1 : 0);
		break;
	case ValueType::Int:
		writeUInt8(2);
		writeInt64(val.asInt());
		break;
	case ValueType::Float:
		writeUInt8(3);
		writeDouble(val.asFloat());
		break;
	case ValueType::String:
		writeUInt8(4);
		writeString(val.string());
		break;
	case ValueType::Struct:
	{
		auto s = val.asStruct();
		writeUInt8(5);
		writeString(s->structName.str());
		writeUInt32(static_cast<u32>(s->fields.size()));
		for (const auto &[fieldName, fieldVal] : s->fields)
		{
			writeString(fieldName.str());
			writeValue(fieldVal); // recurse
		}
		break;
	}
	case ValueType::Array:
	{
		auto a = val.asArray();
		writeUInt8(6);
		writeUInt32(static_cast<u32>(a->size()));
		for (const auto &elem : *a)
		{
			writeValue(elem); // recurse
		}
		break;
	}
	default:
		throw std::runtime_error("BytecodeSerializer::writeValue: unknown ValueType");
	}
}
// ---------------------------------------------------------------------------
// Section writers
// ---------------------------------------------------------------------------
void BytecodeSerializer::writeHeader(u32 dataChecksum)
{
	writeUInt32(MAGIC_NUMBER);
	writeUInt32(VERSION);
	writeUInt32(0); // Flags (reserved)
	writeUInt32(dataChecksum);
}
void BytecodeSerializer::writeConstantPool(const std::vector<Value> &constants)
{
	writeUInt8(SECTION_CONSTANTS);
	writeUInt32(static_cast<u32>(constants.size()));
	for (const auto &val : constants)
	{
		writeValue(val);
	}
}
void BytecodeSerializer::writeVariableMapping(const std::unordered_map<std::string, int> &variables,
                                              int nextVarIndex)
{
	writeUInt8(SECTION_VARIABLES);
	writeUInt32(static_cast<u32>(variables.size()));
	writeInt32(nextVarIndex);
	for (const auto &[name, index] : variables)
	{
		writeString(name);
		writeInt32(index);
	}
}
void BytecodeSerializer::writeInstructions(const std::vector<Instruction> &instructions)
{
	writeUInt8(SECTION_INSTRUCTIONS);
	writeUInt32(static_cast<u32>(instructions.size()));
	for (const auto &instr : instructions)
	{
		writeUInt8(static_cast<u8>(instr.op));
		writeInt32(instr.operand1);
		writeInt32(instr.operand2);
		writeInt32(instr.operand3);
	}
}
void BytecodeSerializer::writeFunctionEntries(const std::unordered_map<std::string, int> &functionEntries)
{
	writeUInt8(SECTION_FUNCTIONS);
	writeUInt32(static_cast<u32>(functionEntries.size()));
	for (const auto &[name, address] : functionEntries)
	{
		writeString(name);
		writeInt32(address);
	}
}
/**
 * @brief Write function type signatures section (0x06).
 *
 * Binary layout:
 *   u8     section_id = 0x06
 *   u32    functionCount
 *   for each function:
 *     string  name
 *     string  returnTypeName   ("any" when unspecified)
 *     u32     paramCount
 *     string  paramTypeName[0..paramCount-1]
 */
void BytecodeSerializer::writeFunctionTypes(
    const std::unordered_map<std::string, std::vector<std::string>> &paramTypeNames,
    const std::unordered_map<std::string, std::string>              &returnTypeNames)
{
	writeUInt8(SECTION_FUNC_TYPES);
	// Only emit entries that have param type info; functions without entries are unknown-typed.
	writeUInt32(static_cast<u32>(paramTypeNames.size()));
	for (const auto &[name, paramTypes] : paramTypeNames)
	{
		writeString(name);
		auto retIt = returnTypeNames.find(name);
		writeString(retIt != returnTypeNames.end() ? retIt->second : "any");
		writeUInt32(static_cast<u32>(paramTypes.size()));
		for (const auto &typeName : paramTypes)
		{
			writeString(typeName);
		}
	}
}
/**
 * @brief Write struct type definitions section (0x05).
 *
 * Binary layout:
 *   u8     section_id = 0x05
 *   u32    structCount
 *   for each StructInfo:
 *     string  name
 *     i32     firstConstIndex
 *     i32     fieldCount
 *     string  fieldName[0..fieldCount-1]
 */
void BytecodeSerializer::writeStructSection(const std::vector<StructInfo> &structs)
{
	writeUInt8(SECTION_STRUCTS);
	writeUInt32(static_cast<u32>(structs.size()));
	for (const auto &info : structs)
	{
		writeString(info.name);
		writeInt32(info.firstConstIndex);
		writeInt32(info.fieldCount);
		for (const auto &fieldName : info.fieldNames)
		{
			writeString(fieldName);
		}
	}
}
void BytecodeSerializer::writeScopeVars(const std::vector<std::vector<std::pair<int, std::string>>> &scopeVarLists)
{
    writeUInt8(SECTION_SCOPE_VARS);
    writeUInt32(static_cast<u32>(scopeVarLists.size()));
    for (const auto &list : scopeVarLists)
    {
        writeUInt32(static_cast<u32>(list.size()));
        for (const auto &[varIndex, varName] : list)
        {
            writeInt32(varIndex);
            writeString(varName);
        }
    }
}
// ---------------------------------------------------------------------------
// Top-level serialize / saveToFile
// ---------------------------------------------------------------------------
std::vector<u8> BytecodeSerializer::serialize(const Bytecode &bytecode)
{
	buffer.clear();
	// Reserve 16 bytes for the header (written after checksum is known).
	for (int i = 0; i < 16; i++)
	{
		buffer.push_back(0);
	}
	size_t dataStartPos = buffer.size();
	writeConstantPool(bytecode.constants);
	writeVariableMapping(bytecode.variables, bytecode.nextVarIndex);
	writeScopeVars(bytecode.scopeVarLists);
	writeFunctionEntries(bytecode.functionEntries);
	writeFunctionTypes(bytecode.functionParamTypeNames, bytecode.functionReturnTypeNames);
	writeStructSection(bytecode.structs);
	writeInstructions(bytecode.instructions);
	std::vector<u8> dataSection(buffer.begin() + dataStartPos, buffer.end());
	u32             checksum = calculateCRC32(dataSection);
	std::vector<u8> tempBuffer = buffer;
	buffer.clear();
	writeHeader(checksum);
	buffer.insert(buffer.end(), tempBuffer.begin() + 16, tempBuffer.end());
	return buffer;
}
bool BytecodeSerializer::saveToFile(const Bytecode &bytecode, const std::filesystem::path &filename)
{
	try
	{
		std::vector<u8> data = serialize(bytecode);
		std::ofstream   file(filename, std::ios::binary);
		if (!file.is_open())
		{
			return false;
		}
		file.write(reinterpret_cast<const char *>(data.data()), data.size());
		return true;
	}
	catch (const std::exception &)
	{
		return false;
	}
}
