bool CCodeGenerator::generate(const Bytecode &bc, const std::filesystem::path &outputPath, const PhsString &modName)
{
	try
	{
		bytecode = &bc;
		output.str("");
		output.clear();
		// Determine module name
		if (modName.empty())
		{
			moduleName = sanitizeModuleName(outputPath.stem().string());
		} else {
			moduleName = sanitizeModuleName(modName);
		}
		// Serialize bytecode to binary format
		BytecodeSerializer serializer;
		serializedBytecode = serializer.serialize(bc);
		// Generate header file with module name, bytecode, and size
		generateFileHeader();
		generateModuleName();
		generateEmbeddedBytecode();
		// Write to file
		std::ofstream file(outputPath);
		if (!file.is_open())
		{
			return false;
		}
		file << output.str();
		file.close();
		return true;
	}
	catch (const std::exception &)
	{
		return false;
	}
}
Bytecode CCodeGenerator::generateBytecodeFromEmbedded(const PhsString &input)
{
	std::vector<unsigned char> bytecodeData = parseEmbeddedBytecode(input);
	BytecodeDeserializer       deserializer;
	return deserializer.deserialize(bytecodeData);
}
void CCodeGenerator::generateFileHeader()
{
	output << "// Phasor VM Program\n";
	output << "// Module: " << moduleName << "\n";
	output << "#pragma once\n";
	output << "#include <stddef.h>\n";
}
void CCodeGenerator::generateModuleName()
{
	output << "const char *moduleName = \"" << moduleName << "\";\n\n";
}
void CCodeGenerator::generateEmbeddedBytecode()
{
#if defined(_WIN32)
	const PhsString sectionPrefixPragma = "#pragma section(\".phsb\", read)\n";
	const PhsString sectionAttr = "__declspec(allocate(\".phsb\")) ";
#elif defined(__APPLE__)
	const PhsString sectionPrefixPragma = "";
	const PhsString sectionAttr = "__attribute__((section(\"__DATA,__phsb\"))) ";
#elif defined(__linux__) || defined(__FreeBSD__) || defined(__OpenBSD__) || defined(__NetBSD__)
	const PhsString sectionPrefixPragma = "";
	const PhsString sectionAttr = "__attribute__((section(\".phsb\"))) ";
#else
	const PhsString sectionPrefixPragma = "";
	const PhsString sectionAttr = "";
#endif
	if (!sectionPrefixPragma.empty())
	{
		output << sectionPrefixPragma;
	}
	output << sectionAttr << "const size_t embeddedBytecodeSize = " << serializedBytecode.size() << ";\n";
	output << sectionAttr << "const unsigned char embeddedBytecode[] = {\n";
	for (size_t i = 0; i < serializedBytecode.size(); i++)
	{
		if (i % 16 == 0)
		{
			output << "\t";
		}
		output << "0x" << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(serializedBytecode[i]);
		if (i < serializedBytecode.size() - 1)
		{
			output << ",";
		}
		if (i % 16 == 15)
		{
			output << "\n";
		}
		else if (i < serializedBytecode.size() - 1)
		{
			output << " ";
		}
	}
	output << std::dec << "\n};\n";
}
std::vector<unsigned char> CCodeGenerator::parseEmbeddedBytecode(const PhsString &input)
{
	std::vector<unsigned char> result;
	std::istringstream         stream(input);
	std::string                token;
	while (stream >> token)
	{
		if (token.size() >= 3 && token[0] == '0' && (token[1] == 'x' || token[1] == 'X'))
		{
			unsigned int       byte;
			std::istringstream hexStream(token);
			hexStream >> std::hex >> byte;
			result.push_back(static_cast<unsigned char>(byte));
		}
	}
	return result;
}
PhsString CCodeGenerator::escapeString(const PhsString &str)
{
	std::ostringstream escaped;
	for (char c : str)
	{
		switch (c)
		{
		case '\\':
			escaped << "\\\\";
			break;
		case '\"':
			escaped << "\\\"";
			break;
		case '\n':
			escaped << "\\n";
			break;
		case '\r':
			escaped << "\\r";
			break;
		case '\t':
			escaped << "\\t";
			break;
		default:
			if (c >= 32 && c <= 126)
			{
				escaped << c;
			} else {
				escaped << "\\x" << std::hex << std::setw(2) << std::setfill('0')
				        << static_cast<int>(static_cast<unsigned char>(c));
			}
			break;
		}
	}
	return escaped.str();
}
PhsString CCodeGenerator::getValueTypeString(ValueType type)
{
	switch (type)
	{
	case ValueType::Null:
		return "Null";
	case ValueType::Bool:
		return "Bool";
	case ValueType::Int:
		return "Int";
	case ValueType::Float:
		return "Float";
	case ValueType::String:
		return "String";
	default:
		return "Unknown";
	}
}
PhsString CCodeGenerator::sanitizeModuleName(const PhsString &name)
{
	PhsString result;
	for (char c : name)
	{
		if ((std::isalnum(c) != 0) || c == '_')
		{
			result += c;
		} else {
			result += '_';
		}
	}
	// Ensure it starts with a letter or underscore
	if (!result.empty() && (std::isdigit(result[0]) != 0))
	{
		result = "_" + result;
	}
	return result.empty() ? "PhasorModule" : result;
}
