int PhasorIR::getOperandCount(OpCode op)
{
    switch (op)
    {
    // 0 operands
    case OpCode::POP:
    case OpCode::IADD:
    case OpCode::ISUBTRACT:
    case OpCode::IMULTIPLY:
    case OpCode::IDIVIDE:
    case OpCode::IMODULO:
    case OpCode::FLADD:
    case OpCode::FLSUBTRACT:
    case OpCode::FLMULTIPLY:
    case OpCode::FLDIVIDE:
    case OpCode::FLMODULO:
    case OpCode::SQRT:
    case OpCode::POW:
    case OpCode::LOG:
    case OpCode::EXP:
    case OpCode::SIN:
    case OpCode::COS:
    case OpCode::TAN:
    case OpCode::NEGATE:
    case OpCode::NOT:
    case OpCode::IAND:
    case OpCode::IOR:
    case OpCode::IEQUAL:
    case OpCode::INOT_EQUAL:
    case OpCode::ILESS_THAN:
    case OpCode::IGREATER_THAN:
    case OpCode::ILESS_EQUAL:
    case OpCode::IGREATER_EQUAL:
    case OpCode::FLEQUAL:
    case OpCode::FLNOT_EQUAL:
    case OpCode::FLLESS_THAN:
    case OpCode::FLGREATER_THAN:
    case OpCode::FLLESS_EQUAL:
    case OpCode::FLGREATER_EQUAL:
    case OpCode::PRINT:
    case OpCode::PRINTERROR:
    case OpCode::READLINE:
    case OpCode::HALT:
    case OpCode::RETURN:
    case OpCode::TRUE_P:
    case OpCode::FALSE_P:
    case OpCode::NULL_VAL:
    case OpCode::LEN:
    case OpCode::CHAR_AT:
    case OpCode::SUBSTR:
    case OpCode::NEW_ARR:
    case OpCode::LOAD_ARR:
    case OpCode::STORE_ARR:
    case OpCode::GET_FIELD_DYN:
        return 0;
    // 1 operand
    case OpCode::PUSH_CONST:
    case OpCode::JUMP:
    case OpCode::JUMP_IF_FALSE:
    case OpCode::JUMP_IF_TRUE:
    case OpCode::JUMP_BACK:
    case OpCode::STORE_VAR:
    case OpCode::LOAD_VAR:
    case OpCode::CALL_NATIVE:
    case OpCode::CALL:
    case OpCode::SYSTEM:
    case OpCode::SYSTEM_OUT:
    case OpCode::SYSTEM_ERR:
    case OpCode::PUSH_R:
    case OpCode::POP_R:
    case OpCode::PRINT_R:
    case OpCode::PRINTERROR_R:
    case OpCode::READLINE_R:
    case OpCode::SYSTEM_R:
    case OpCode::SYSTEM_OUT_R:
    case OpCode::SYSTEM_ERR_R:
    case OpCode::NEW_STRUCT:
    case OpCode::GET_FIELD:
    case OpCode::SET_FIELD:
    case OpCode::NEW_STRUCT_INSTANCE_STATIC:
    case OpCode::EXIT_SCOPE:
        return 1;
    // 2 operands
    case OpCode::MOV:
    case OpCode::LOAD_CONST_R:
    case OpCode::LOAD_VAR_R:
    case OpCode::STORE_VAR_R:
    case OpCode::SQRT_R:
    case OpCode::LOG_R:
    case OpCode::EXP_R:
    case OpCode::SIN_R:
    case OpCode::COS_R:
    case OpCode::TAN_R:
    case OpCode::NEG_R:
    case OpCode::NOT_R:
    case OpCode::PUSH2_R:
    case OpCode::POP2_R:
    case OpCode::GET_FIELD_STATIC:
    case OpCode::SET_FIELD_STATIC:
        return 2;
    // 3 operands
    case OpCode::IADD_R:
    case OpCode::ISUB_R:
    case OpCode::IMUL_R:
    case OpCode::IDIV_R:
    case OpCode::IMOD_R:
    case OpCode::FLADD_R:
    case OpCode::FLSUB_R:
    case OpCode::FLMUL_R:
    case OpCode::FLDIV_R:
    case OpCode::FLMOD_R:
    case OpCode::POW_R:
    case OpCode::IAND_R:
    case OpCode::IOR_R:
    case OpCode::IEQ_R:
    case OpCode::INE_R:
    case OpCode::ILT_R:
    case OpCode::IGT_R:
    case OpCode::ILE_R:
    case OpCode::IGE_R:
    case OpCode::FLAND_R:
    case OpCode::FLOR_R:
    case OpCode::FLEQ_R:
    case OpCode::FLNE_R:
    case OpCode::FLLT_R:
    case OpCode::FLGT_R:
    case OpCode::FLLE_R:
    case OpCode::FLGE_R:
        return 3;
    default:
        return 0;
    }
}
PhasorIR::OperandType PhasorIR::getOperandType(OpCode op, int operandIndex)
{
    // Stack operations with special indices
    if (op == OpCode::PUSH_CONST && operandIndex == 0)
    {
        return OperandType::CONSTANT_IDX;
    }
    if (op == OpCode::STORE_VAR && operandIndex == 0)
    {
        return OperandType::VARIABLE_IDX;
    }
    if (op == OpCode::LOAD_VAR && operandIndex == 0)
    {
        return OperandType::VARIABLE_IDX;
    }
    if (op == OpCode::CALL_NATIVE && operandIndex == 0)
    {
        return OperandType::CONSTANT_IDX;
    }
    if (op == OpCode::CALL && operandIndex == 0)
    {
        return OperandType::FUNCTION_IDX;
    }
    if (op == OpCode::SYSTEM && operandIndex == 0)
    {
        return OperandType::CONSTANT_IDX;
    }
    if (op == OpCode::EXIT_SCOPE && operandIndex == 0)
    {
        return OperandType::SCOPE_IDX;
    }
    // Register operations with mixed types
    if (op == OpCode::LOAD_CONST_R)
    {
        if (operandIndex == 0) 
        {
            return OperandType::REGISTER;
        }
        if (operandIndex == 1)
        {
            return OperandType::CONSTANT_IDX;
        }
    }
    if (op == OpCode::LOAD_VAR_R)
    {
        if (operandIndex == 0)
        { 
            return OperandType::REGISTER;
        }
        if (operandIndex == 1)
        {
            return OperandType::VARIABLE_IDX;
        }
    }
    if (op == OpCode::STORE_VAR_R)
    {
        if (operandIndex == 0)
        {
            return OperandType::REGISTER;
        }
        if (operandIndex == 1) 
        { 
            return OperandType::VARIABLE_IDX;
        }
    }
    // JUMP instructions take an offset (INT)
    if (op == OpCode::JUMP || op == OpCode::JUMP_IF_FALSE ||
        op == OpCode::JUMP_IF_TRUE || op == OpCode::JUMP_BACK) 
    {
        return OperandType::INT;
    }
    // Register ops use REGISTER for all operands
    if (static_cast<int>(op) >= static_cast<int>(OpCode::MOV))
    {
        return OperandType::REGISTER;
    }
    return OperandType::INT;
}
PhsString PhasorIR::escapeString(const PhsString &str)
{
    std::stringstream ss;
    for (unsigned char c : str)
    {
        switch (c)
        {
        case '\a':   ss << "\\a";   break;
        case '\b':   ss << "\\b";   break;
        case '\f':   ss << "\\f";   break;
        case '\n':   ss << "\\n";   break;
        case '\r':   ss << "\\r";   break;
        case '\t':   ss << "\\t";   break;
        case '\v':   ss << "\\v";   break;
        case '\x1b': ss << "\\e";   break;
        case '\\':   ss << "\\\\";  break;
        case '"':    ss << "\\\"";  break;
        default:
            if (c < 0x20 || c == 0x7F)
            {
                ss << "\\x"
                   << "0123456789abcdef"[c >> 4]
                   << "0123456789abcdef"[c & 0xF];
            }
            else
            {
                ss << static_cast<char>(c);
            }
            break;
        }
    }
    return ss.str();
}
PhsString PhasorIR::unescapeString(const PhsString &str)
{
    PhsString result;
    size_t      len = str.length();
    auto hexVal = [](char c) -> int 
    {
        if (c >= '0' && c <= '9')
        {
            return c - '0';
        }
        if (c >= 'a' && c <= 'f')
        {
            return c - 'a' + 10;
        }
        if (c >= 'A' && c <= 'F')
        { 
            return c - 'A' + 10;
        }
        return -1;
    };
    for (size_t i = 0; i < len; ++i)
    {
        if (str[i] != '\\' || i + 1 >= len)
        {
            result += str[i];
            continue;
        }
        char esc = str[++i];
        switch (esc)
        {
        case 'a':  result += '\a'; break;
        case 'b':  result += '\b'; break;
        case 'f':  result += '\f'; break;
        case 'n':  result += '\n'; break;
        case 'r':  result += '\r'; break;
        case 't':  result += '\t'; break;
        case 'v':  result += '\v'; break;
        case '\\': result += '\\'; break;
        case '\'': result += '\''; break;
        case '"':  result += '"';  break;
        case 'e':
        case 'E':  result += '\x1b'; break;
        case '0': case '1': case '2': case '3':
        case '4': case '5': case '6': case '7':
        {
            u32 val = static_cast<u32>(esc - '0');
            for (int k = 1; k < 3 && i + 1 < len; ++k)
            {
                char d = str[i + 1];
                if (d < '0' || d > '7')
                {
                    break;
                }
                val = val * 8 + static_cast<u32>(d - '0');
                ++i;
            }
            result += static_cast<char>(val & 0xFF);
            break;
        }
        case 'x':
        {
            if (i + 1 >= len || hexVal(str[i + 1]) < 0)
            { 
                result += esc;
                break;
            }
            int val = hexVal(str[++i]);
            if (i + 1 < len && hexVal(str[i + 1]) >= 0)
            {
                val = (val << 4) | hexVal(str[++i]);
            }
            result += static_cast<char>(val);
            break;
        }
        case 'u':
        case 'U':
        {
            int  ndigits = (esc == 'u') ? 4 : 8;
            u32  cp      = 0;
            bool ok      = true;
            for (int k = 0; k < ndigits; ++k)
            {
                if (i + 1 >= len || hexVal(str[i + 1]) < 0)
                {
                    ok = false; 
                    break;
                }
                cp = (cp << 4) | static_cast<u32>(hexVal(str[++i]));
            }
            if (!ok || cp > 0x10FFFF || (cp >= 0xD800 && cp <= 0xDFFF))
            {
                result += esc; break;
            }
            if (cp <= 0x7F)
            { 
                result += static_cast<char>(cp);
            } else if (cp <= 0x7FF)  { 
                result += static_cast<char>(0xC0 | (cp >> 6));
                result += static_cast<char>(0x80 | (cp & 0x3F));
            } else if (cp <= 0xFFFF) { 
                result += static_cast<char>(0xE0 | (cp >> 12));
                result += static_cast<char>(0x80 | ((cp >> 6) & 0x3F));
                result += static_cast<char>(0x80 | (cp & 0x3F));
            } else { 
                result += static_cast<char>(0xF0 | (cp >> 18));
                result += static_cast<char>(0x80 | ((cp >> 12) & 0x3F));
                result += static_cast<char>(0x80 | ((cp >> 6) & 0x3F));
                result += static_cast<char>(0x80 | (cp & 0x3F)); }
            break;
        }
        default:
            result += '\\';
            result += esc;
            break;
        }
    }
    return result;
}
// ---------------------------------------------------------------------------
// Helper: write a single Value to a stringstream
// ---------------------------------------------------------------------------
static void writeIRValue(std::stringstream &ss, const Value &val,
                         const std::function<std::string(const std::string &)> &escape)
{
    switch (val.getType())
    {
    case ValueType::Null:
        ss << "NULL\n";
        break;
    case ValueType::Bool:
        ss << "BOOL " << (val.asBool() ? "true" : "false") << "\n";
        break;
    case ValueType::Int:
        ss << "INT " << val.asInt() << "\n";
        break;
    case ValueType::Float:
        ss << "FLOAT " << val.asFloat() << "\n";
        break;
    case ValueType::String:
        ss << "STRING \"" << escape(val.string()) << "\"\n";
        break;
    case ValueType::Struct:
    {
        auto structPtr = val.asStruct();
        if (!structPtr)
        {
            throw std::runtime_error("PhasorIR::serialize: null struct pointer");
        }
        ss << "STRUCT \"" << escape(structPtr->structName) << "\" " << structPtr->fields.size() << "\n";
        for (const auto &[fieldName, fieldVal] : structPtr->fields)
        {
            ss << "  FIELD " << fieldName << " ";
            writeIRValue(ss, fieldVal, escape);
        }
        break;
    }
    case ValueType::Array:
    {
        auto arrayPtr = val.asArray();
        if (!arrayPtr)
        {
            throw std::runtime_error("PhasorIR::serialize: null array pointer");
        }
        ss << "ARRAY " << arrayPtr->size() << "\n";
        for (const auto &elem : *arrayPtr)
        {
            ss << "  ELEM ";
            writeIRValue(ss, elem, escape);
        }
        break;
    }
    default:
        throw std::runtime_error("PhasorIR::serialize: unknown ValueType");
    }
}
// ---------------------------------------------------------------------------
// Helper: read a single Value from a stringstream
// ---------------------------------------------------------------------------
static Value readIRValue(const std::string &type, std::stringstream &ss,
                         const std::function<std::string(const std::string &)> &unescape)
{
    if (type == "NULL")
    {
        return Value{};
    }
    if (type == "BOOL")
    {
        std::string b;
        ss >> b;
        return Value{b == "true"};
    }
    else if (type == "INT")
    {
        i64 v;
        ss >> v;
        return Value{v};
    }
    else if (type == "FLOAT")
    {
        f64 v;
        ss >> v;
        return Value{v};
    }
    else if (type == "STRING")
    {
        std::string s;
        char        c;
        while (ss.get(c) && c != '"') {}
        std::getline(ss, s, '"');
        return Value{unescape(s)};
    }
    else if (type == "STRUCT")
    {
        std::string typeName;
        int         fieldCount = 0;
        char qc;
        while (ss.get(qc) && qc != '"') {}
        std::getline(ss, typeName, '"');
        typeName = unescape(typeName);
        ss >> fieldCount;
        auto structInstance = std::make_shared<Value::StructInstance>();
        structInstance->structName = PhsString(typeName);
        for (int f = 0; f < fieldCount; ++f)
        {
            std::string keyword, fieldName, fieldType;
            ss >> keyword;   // "FIELD"
            ss >> fieldName;
            ss >> fieldType;
            structInstance->fields[fieldName] = readIRValue(fieldType, ss, unescape);
        }
        return Value{std::move(structInstance)};
    }
    else if (type == "ARRAY")
    {
        int elementCount = 0;
        ss >> elementCount;
        auto arrayInstance = std::make_shared<Value::ArrayInstance>();
        arrayInstance->reserve(static_cast<size_t>(elementCount));
        for (int e = 0; e < elementCount; ++e)
        {
            std::string keyword, elemType;
            ss >> keyword;  // "ELEM"
            ss >> elemType;
            arrayInstance->push_back(readIRValue(elemType, ss, unescape));
        }
        return Value{std::move(arrayInstance)};
    }
    else
    {
        throw std::runtime_error("PhasorIR: unknown value type tag: " + type);
    }
}
// ---------------------------------------------------------------------------
// serialize
// ---------------------------------------------------------------------------
std::vector<u8> PhasorIR::serialize(const Bytecode &bytecode)
{
    std::stringstream ss;
    // Header
    ss << ".PHIR 3.0.0\n";
    // Build reverse lookup maps for inline comments
    std::map<int, std::string> indexToVarName;
    for (const auto &[name, index] : bytecode.variables)
    {
        indexToVarName[index] = name;
    }
    std::map<int, std::string> addressToFuncName;
    for (const auto &[name, address] : bytecode.functionEntries)
    {
        addressToFuncName[address] = name;
    }
    // Constants Section
    ss << ".CONSTANTS " << bytecode.constants.size() << "\n";
    for (const auto &val : bytecode.constants)
    {
        writeIRValue(ss, val, escapeString);
    }
    // Variables Section
    ss << ".VARIABLES " << bytecode.variables.size() << " " << bytecode.nextVarIndex << "\n";
    for (const auto &[name, index] : bytecode.variables)
    {
        ss << name << " " << index << "\n";
    }
    // Scopes Section
    ss << ".SCOPES " << bytecode.scopeVarLists.size() << "\n";
    for (const auto &varList : bytecode.scopeVarLists)
    {
        ss << varList.size();
        for (const auto &[idx, name] : varList)
        {
            ss << " " << idx << " " << name;
        }
        ss << "\n";
    }
    // Functions Section
    ss << ".FUNCTIONS " << bytecode.functionEntries.size() << "\n";
    for (const auto &[name, address] : bytecode.functionEntries)
    {
        ss << name << " " << address << "\n";
    }
    // Function Type Signatures Section
    // Format per line: <name> <returnType> <paramCount> [<paramType>...]
    ss << ".FUNCTYPES " << bytecode.functionParamTypeNames.size() << "\n";
    for (const auto &[name, paramTypes] : bytecode.functionParamTypeNames)
    {
        auto retIt = bytecode.functionReturnTypeNames.find(name);
        const std::string &retType = (retIt != bytecode.functionReturnTypeNames.end()) ? retIt->second : "any";
        ss << name << " " << retType << " " << paramTypes.size();
        for (const auto &typeName : paramTypes)
        {
            ss << " " << typeName;
        }
        ss << "\n";
    }
    // Structs Section
    ss << ".STRUCTS " << bytecode.structs.size() << "\n";
    for (const auto &info : bytecode.structs)
    {
        ss << info.name << " " << info.firstConstIndex << " " << info.fieldCount;
        for (const auto &fieldName : info.fieldNames)
        {
            ss << " " << fieldName;
        }
        ss << "\n";
    }
    // Instructions Section
    ss << ".INSTRUCTIONS " << bytecode.instructions.size() << "\n";
    for (const auto &instr : bytecode.instructions)
    {
        std::stringstream instrLine;
        instrLine << opCodeToString(instr.op);
        int     operandCount       = getOperandCount(instr.op);
        i32     operands[3]        = {instr.operand1, instr.operand2, instr.operand3};
        PhsString comment;
        for (int i = 0; i < operandCount; ++i)
        {
            OperandType type = getOperandType(instr.op, i);
            if (i > 0)
            { 
                instrLine << ",";
            }
            instrLine << " ";
            switch (type)
            {
            case OperandType::REGISTER:
                instrLine << "r" << operands[i];
                break;
            case OperandType::CONSTANT_IDX:
                instrLine << operands[i];
                if (operands[i] >= 0 && std::cmp_less(operands[i], bytecode.constants.size()))
                {
                    const Value &v = bytecode.constants[operands[i]];
                    if (v.getType() == ValueType::String)
                    {
                        PhsString str = v.string();
                        if (str.length() > 20) 
                        {
                            str = str.substr(0, 20) + "...";
                        }
                        comment = "const[" + std::to_string(operands[i]) + "]=\"" + escapeString(str) + "\"";
                    } else if (v.getType() == ValueType::Int) {
                        comment = PhsString("const[" + std::to_string(operands[i]) + "]=" + std::to_string(v.asInt()));
                    } else if (v.getType() == ValueType::Float) {
                        comment = PhsString("const[" + std::to_string(operands[i]) + "]=" + std::to_string(v.asFloat()));
}
                }
                break;
            case OperandType::VARIABLE_IDX:
                instrLine << operands[i];
                if (indexToVarName.contains(operands[i]))
                {
                    comment = PhsString("var=" + indexToVarName[operands[i]]);
                }
                break;
            case OperandType::FUNCTION_IDX:
                instrLine << operands[i];
                if (addressToFuncName.contains(operands[i]))
                {
                    comment = PhsString("func=" + addressToFuncName[operands[i]]);
                }
                break;
            case OperandType::SCOPE_IDX:
                instrLine << operands[i];
                break;
            default:
                instrLine << operands[i];
                break;
            }
        }
        PhsString lineStr = instrLine.str();
        if (!comment.empty())
        {
            const size_t commentColumn = 40;
            if (lineStr.length() < commentColumn)
            {
                lineStr.append(commentColumn - lineStr.length(), ' ');
            } else {
                lineStr += " ";
            }
            lineStr += "; " + comment;
        }
        ss << lineStr << "\n";
    }
    PhsString     textData = ss.str();
    std::vector<u8> buffer;
    buffer.insert(buffer.end(), textData.begin(), textData.end());
    return buffer;
}
// ---------------------------------------------------------------------------
// deserialize
// ---------------------------------------------------------------------------
Bytecode PhasorIR::deserialize(const std::vector<u8> &data)
{
    if (data.size() < 8)
    {
        throw std::runtime_error("Invalid Phasor IR file: too small");
    }
    std::string       textData(data.begin() + 8, data.end());
    std::stringstream ss(textData);
    std::string       section;
    Bytecode          bytecode;
    while (ss >> section)
    {
        if (section == ".PHIR")
        {
            std::string version;
            ss >> version;
            if (version < "3.0.0")
            {
                throw std::runtime_error("Incompatible Phasor IR version");
            }
        }
        else if (section == ".CONSTANTS")
        {
            int count;
            ss >> count;
            bytecode.constants.reserve(count);
            for (int i = 0; i < count; ++i)
            {
                std::string type;
                ss >> type;
                bytecode.constants.push_back(readIRValue(type, ss, unescapeString));
            }
        }
        else if (section == ".VARIABLES")
        {
            int count;
            ss >> count >> bytecode.nextVarIndex;
            for (int i = 0; i < count; ++i)
            {
                std::string name;
                int         index;
                ss >> name >> index;
                bytecode.variables[name] = index;
            }
        }
        else if (section == ".SCOPES")
        {
            int count;
            ss >> count;
            bytecode.scopeVarLists.resize(count);
            for (int i = 0; i < count; ++i)
            {
                int varCount;
                ss >> varCount;
                bytecode.scopeVarLists[i].reserve(varCount);
                for (int j = 0; j < varCount; ++j)
                {
                    int idx;
                    std::string name;
                    ss >> idx >> name;
                    bytecode.scopeVarLists[i].emplace_back(idx, name);
                }
            }
        }
        else if (section == ".FUNCTIONS")
        {
            int count;
            ss >> count;
            for (int i = 0; i < count; ++i)
            {
                std::string name;
                int         address;
                ss >> name >> address;
                bytecode.functionEntries[name] = address;
            }
        }
        else if (section == ".FUNCTYPES")
        {
            int count;
            ss >> count;
            for (int i = 0; i < count; ++i)
            {
                std::string name;
                std::string retType;
                int         paramCount;
                ss >> name >> retType >> paramCount;
                std::vector<std::string> paramTypes;
                paramTypes.reserve(static_cast<size_t>(paramCount));
                for (int p = 0; p < paramCount; ++p)
                {
                    std::string typeName;
                    ss >> typeName;
                    paramTypes.push_back(std::move(typeName));
                }
                bytecode.functionParamTypeNames[name]  = std::move(paramTypes);
                bytecode.functionReturnTypeNames[name]  = std::move(retType);
                bytecode.functionParamCounts[name]      = paramCount;
            }
        }
        else if (section == ".STRUCTS")
        {
            int count;
            ss >> count;
            for (int i = 0; i < count; ++i)
            {
                StructInfo info;
                ss >> info.name >> info.firstConstIndex >> info.fieldCount;
                info.fieldNames.clear();
                for (int f = 0; f < info.fieldCount; ++f)
                {
                    std::string fieldName;
                    ss >> fieldName;
                    info.fieldNames.push_back(fieldName);
                }
                int index = static_cast<int>(bytecode.structs.size());
                bytecode.structs.push_back(std::move(info));
                bytecode.structEntries[bytecode.structs.back().name] = index;
            }
        }
        else if (section == ".INSTRUCTIONS")
        {
            int count;
            ss >> count;
            bytecode.instructions.reserve(count);
            for (int i = 0; i < count; ++i)
            {
                std::string opStr;
                ss >> opStr;
                OpCode  op           = stringToOpCode(opStr);
                int     operandCount = getOperandCount(op);
                i32     operands[3]  = {0, 0, 0};
                for (int j = 0; j < operandCount; ++j)
                {
                    std::string token;
                    ss >> token;
                    if (token.empty() || token[0] == ';')
                    {
                        std::getline(ss, token);
                        break;
                    }
                    if (!token.empty() && token.back() == ',')
                    {
                        token.pop_back();
                    }
                    if (!token.empty() && token[0] == 'r')
                    {
                        operands[j] = std::stoi(token.substr(1));
                    } else {
                        operands[j] = std::stoi(token);
                    }
                }
                // Skip any remaining content on the line (comments)
                char c;
                while (ss.get(c) && c != '\n') {}
                bytecode.instructions.emplace_back(op, operands[0], operands[1], operands[2]);
            }
        }
    }
    return bytecode;
}
// ---------------------------------------------------------------------------
// saveToFile / loadFromFile
// ---------------------------------------------------------------------------
bool PhasorIR::saveToFile(const Bytecode &bytecode, const std::filesystem::path &filename)
{
    try
    {
        std::vector<u8> data = serialize(bytecode);
        std::ofstream   file(filename, std::ios::binary);
        if (!file.is_open())
        {
            return false;
        }
        file.write(reinterpret_cast<const char *>(data.data()), (std::streamsize)data.size());
        return true;
    }
    catch (...)
    {
        return false;
    }
}
Bytecode PhasorIR::loadFromFile(const std::filesystem::path &filename)
{
    std::ifstream file(filename, std::ios::binary | std::ios::ate);
    if (!file.is_open())
    {
        throw std::runtime_error("Cannot open file");
    }
    std::streamsize size = file.tellg();
    file.seekg(0, std::ios::beg);
    std::vector<u8> buffer(size);
    if (!file.read(reinterpret_cast<char *>(buffer.data()), size))
    {
        throw std::runtime_error("Cannot read file");
    }
    return deserialize(buffer);
}
} // namespace Phasor#pragma once
#include "../Bytecode.hpp"
#include <cstdint>
#include <filesystem>
#include <string>
#include <unordered_map>
#include <vector>
#include <phsint.hpp>
/// @brief The Phasor Programming Language and Runtime
namespace Phasor
{
/**
 * @class PhasorIR
 * @brief Phasor IR Serializer/Deserializer
 */
class PhasorIR
{
  public:
	/// @brief Serialize bytecode to Phasor IR format
	static std::vector<u8> serialize(const Bytecode &bytecode);
	/// @brief Deserialize Phasor IR format to bytecode
	static Bytecode deserialize(const std::vector<u8> &data);
	/// @brief Save bytecode to .phir file
	static bool saveToFile(const Bytecode &bytecode, const std::filesystem::path &filename);
	/// @brief Load bytecode from .phir file
	static Bytecode loadFromFile(const std::filesystem::path &filename);
	/// @brief Helper to escape strings for text format
	static PhsString escapeString(const PhsString &str);
	/// @brief Helper to unescape strings from text format
	static PhsString unescapeString(const PhsString &str);
  private:
	/// @brief Operand types for instructions
	enum class OperandType : u8
	{
		NONE,         ///< No operand
		INT,          ///< Integer operand
		REGISTER,     ///< Register operand
		CONSTANT_IDX, ///< Index into constant pool
		VARIABLE_IDX, ///< Index into variable mapping
		FUNCTION_IDX,  ///< Index into function entries
		SCOPE_IDX
	};
	static int         getOperandCount(OpCode op);
	static OperandType getOperandType(OpCode op, int operandIndex);
	static const std::unordered_map<OpCode, PhsString> opCodeToStringMap;
	static const std::unordered_map<PhsString, OpCode> stringToOpCodeMap;
};
} // namespace Phasor#include "../../Runtime/VM/VM.hpp"
#include "../../Runtime/Stdlib/StdLib.hpp"
#include "../../ISA/map.hpp"
namespace Phasor 
{
inline Value bytecodeToValue(const Bytecode &bc)
{
	Value root = Value::createStruct("Bytecode");
	std::vector<Value> instrElems;
	instrElems.reserve(bc.instructions.size());
	for (const auto &instr : bc.instructions)
	{
		Value iv = Value::createStruct("Instruction");
		iv["op"] = Value(static_cast<i64>(static_cast<int>(instr.op)));
		iv["o1"] = Value(static_cast<i64>(instr.operand1));
		iv["o2"] = Value(static_cast<i64>(instr.operand2));
		iv["o3"] = Value(static_cast<i64>(instr.operand3));
		instrElems.push_back(std::move(iv));
	}
	root["instructions"] = Value::createArray(std::move(instrElems));
	root["constants"] = Value::createArray(bc.constants);
	Value variablesMap = Value::createStruct("Map");
	for (const auto &[varKey, varVal] : bc.variables)
		variablesMap[PhsString(varKey)] = Value(static_cast<i64>(varVal));
	root["variables"] = variablesMap;
	std::vector<Value> scopeOuter;
	scopeOuter.reserve(bc.scopeVarLists.size());
	for (const auto &scope : bc.scopeVarLists)
	{
		std::vector<Value> scopeInner;
		scopeInner.reserve(scope.size());
		for (const auto &[scopeIdx, scopeName] : scope)
		{
			Value pair = Value::createStruct("ScopeVar");
			pair["index"] = Value(static_cast<i64>(scopeIdx));
			pair["name"]  = Value(scopeName);
			scopeInner.push_back(std::move(pair));
		}
		scopeOuter.push_back(Value::createArray(std::move(scopeInner)));
	}
	root["scopeVarLists"] = Value::createArray(std::move(scopeOuter));
	Value functionEntriesMap = Value::createStruct("Map");
	for (const auto &[feKey, feVal] : bc.functionEntries)
		functionEntriesMap[PhsString(feKey)] = Value(static_cast<i64>(feVal));
	root["functionEntries"] = functionEntriesMap;
	Value functionParamCountsMap = Value::createStruct("Map");
	for (const auto &[fpcKey, fpcVal] : bc.functionParamCounts)
		functionParamCountsMap[PhsString(fpcKey)] = Value(static_cast<i64>(fpcVal));
	root["functionParamCounts"] = functionParamCountsMap;
	Value functionParamTypeNamesMap = Value::createStruct("Map");
	for (const auto &[fptnKey, fptnVec] : bc.functionParamTypeNames)
	{
		std::vector<Value> fptnElems;
		fptnElems.reserve(fptnVec.size());
		for (const auto &fptnStr : fptnVec)
			fptnElems.emplace_back(fptnStr);
		functionParamTypeNamesMap[PhsString(fptnKey)] = Value::createArray(std::move(fptnElems));
	}
	root["functionParamTypeNames"] = functionParamTypeNamesMap;
	Value functionParamArrayDimsMap = Value::createStruct("Map");
	for (const auto &[fpadKey, fpadOuterVec] : bc.functionParamArrayDims)
	{
		std::vector<Value> fpadOuter;
		fpadOuter.reserve(fpadOuterVec.size());
		for (const auto &fpadInnerVec : fpadOuterVec)
		{
			std::vector<Value> fpadInner;
			fpadInner.reserve(fpadInnerVec.size());
			for (int fpadDim : fpadInnerVec)
				fpadInner.emplace_back(static_cast<i64>(fpadDim));
			fpadOuter.push_back(Value::createArray(std::move(fpadInner)));
		}
		functionParamArrayDimsMap[PhsString(fpadKey)] = Value::createArray(std::move(fpadOuter));
	}
	root["functionParamArrayDims"] = functionParamArrayDimsMap;
	Value functionReturnTypeNamesMap = Value::createStruct("Map");
	for (const auto &[frtnKey, frtnVal] : bc.functionReturnTypeNames)
		functionReturnTypeNamesMap[PhsString(frtnKey)] = Value(frtnVal);
	root["functionReturnTypeNames"] = functionReturnTypeNamesMap;
	Value functionReturnArrayDimsMap = Value::createStruct("Map");
	for (const auto &[fradKey, fradVec] : bc.functionReturnArrayDims)
	{
		std::vector<Value> fradElems;
		fradElems.reserve(fradVec.size());
		for (int fradDim : fradVec)
			fradElems.emplace_back(static_cast<i64>(fradDim));
		functionReturnArrayDimsMap[PhsString(fradKey)] = Value::createArray(std::move(fradElems));
	}
	root["functionReturnArrayDims"] = functionReturnArrayDimsMap;
	root["nextVarIndex"] = Value(static_cast<i64>(bc.nextVarIndex));
	std::vector<Value> structElems;
	structElems.reserve(bc.structs.size());
	for (const auto &si : bc.structs)
	{
		Value sv = Value::createStruct("StructInfo");
		sv["name"]            = Value(si.name);
		sv["firstConstIndex"] = Value(static_cast<i64>(si.firstConstIndex));
		sv["fieldCount"]      = Value(static_cast<i64>(si.fieldCount));
		std::vector<Value> fieldNamesElems;
		fieldNamesElems.reserve(si.fieldNames.size());
		for (const auto &fn : si.fieldNames)
			fieldNamesElems.emplace_back(fn);
		sv["fieldNames"] = Value::createArray(std::move(fieldNamesElems));
		std::vector<Value> fieldArrayDimsElems;
		fieldArrayDimsElems.reserve(si.fieldArrayDims.size());
		for (const auto &dims : si.fieldArrayDims)
		{
			std::vector<Value> dimElems;
			dimElems.reserve(dims.size());
			for (int d : dims)
				dimElems.emplace_back(static_cast<i64>(d));
			fieldArrayDimsElems.push_back(Value::createArray(std::move(dimElems)));
		}
		sv["fieldArrayDims"] = Value::createArray(std::move(fieldArrayDimsElems));
		std::vector<Value> fieldTypeNamesElems;
		fieldTypeNamesElems.reserve(si.fieldTypeNames.size());
		for (const auto &ftn : si.fieldTypeNames)
			fieldTypeNamesElems.emplace_back(ftn);
		sv["fieldTypeNames"] = Value::createArray(std::move(fieldTypeNamesElems));
		structElems.push_back(std::move(sv));
	}
	root["structs"] = Value::createArray(std::move(structElems));
	Value structEntriesMap = Value::createStruct("Map");
	for (const auto &[seKey, seVal] : bc.structEntries)
		structEntriesMap[PhsString(seKey)] = Value(static_cast<i64>(seVal));
	root["structEntries"] = structEntriesMap;
	return root;
}
inline Bytecode bytecodeFromValue(const Value &root)
{
	Bytecode bc;
	auto instrArr = root.getField("instructions").asArray();
	bc.instructions.reserve(instrArr->size());
	for (const auto &iv : *instrArr)
	{
		Instruction instr;
		instr.op       = static_cast<OpCode>(iv.getField("op").asInt());
		instr.operand1 = static_cast<i32>(iv.getField("o1").asInt());
		instr.operand2 = static_cast<i32>(iv.getField("o2").asInt());
		instr.operand3 = static_cast<i32>(iv.getField("o3").asInt());
		bc.instructions.push_back(instr);
	}
	auto constArr = root.getField("constants").asArray();
	bc.constants.reserve(constArr->size());
	for (const auto &cv : *constArr)
		bc.constants.push_back(cv);
	auto variablesStruct = root.getField("variables").asStruct();
	for (const auto &[varKey, varVal] : variablesStruct->fields)
		bc.variables[varKey.str()] = static_cast<int>(varVal.asInt());
	auto scopeOuterArr = root.getField("scopeVarLists").asArray();
	bc.scopeVarLists.reserve(scopeOuterArr->size());
	for (const auto &scopeVal : *scopeOuterArr)
	{
		std::vector<std::pair<int, std::string>> scope;
		auto scopeInnerArr = scopeVal.asArray();
		scope.reserve(scopeInnerArr->size());
		for (const auto &pairVal : *scopeInnerArr)
			scope.emplace_back(static_cast<int>(pairVal.getField("index").asInt()),
			                    pairVal.getField("name").stl_string());
		bc.scopeVarLists.push_back(std::move(scope));
	}
	auto functionEntriesStruct = root.getField("functionEntries").asStruct();
	for (const auto &[feKey, feVal] : functionEntriesStruct->fields)
		bc.functionEntries[feKey.str()] = static_cast<int>(feVal.asInt());
	auto functionParamCountsStruct = root.getField("functionParamCounts").asStruct();
	for (const auto &[fpcKey, fpcVal] : functionParamCountsStruct->fields)
		bc.functionParamCounts[fpcKey.str()] = static_cast<int>(fpcVal.asInt());
	auto functionParamTypeNamesStruct = root.getField("functionParamTypeNames").asStruct();
	for (const auto &[fptnKey, fptnVal] : functionParamTypeNamesStruct->fields)
	{
		std::vector<std::string> fptnVec;
		auto fptnArr = fptnVal.asArray();
		fptnVec.reserve(fptnArr->size());
		for (const auto &fptnElem : *fptnArr)
			fptnVec.push_back(fptnElem.stl_string());
		bc.functionParamTypeNames[fptnKey.str()] = std::move(fptnVec);
	}
	auto functionParamArrayDimsStruct = root.getField("functionParamArrayDims").asStruct();
	for (const auto &[fpadKey, fpadVal] : functionParamArrayDimsStruct->fields)
	{
		std::vector<std::vector<int>> fpadOuterVec;
		auto fpadOuterArr = fpadVal.asArray();
		fpadOuterVec.reserve(fpadOuterArr->size());
		for (const auto &fpadInnerVal : *fpadOuterArr)
		{
			std::vector<int> fpadInnerVec;
			auto fpadInnerArr = fpadInnerVal.asArray();
			fpadInnerVec.reserve(fpadInnerArr->size());
			for (const auto &fpadDimVal : *fpadInnerArr)
				fpadInnerVec.push_back(static_cast<int>(fpadDimVal.asInt()));
			fpadOuterVec.push_back(std::move(fpadInnerVec));
		}
		bc.functionParamArrayDims[fpadKey.str()] = std::move(fpadOuterVec);
	}
	auto functionReturnTypeNamesStruct = root.getField("functionReturnTypeNames").asStruct();
	for (const auto &[frtnKey, frtnVal] : functionReturnTypeNamesStruct->fields)
		bc.functionReturnTypeNames[frtnKey.str()] = frtnVal.stl_string();
	auto functionReturnArrayDimsStruct = root.getField("functionReturnArrayDims").asStruct();
	for (const auto &[fradKey, fradVal] : functionReturnArrayDimsStruct->fields)
	{
		std::vector<int> fradVec;
		auto fradArr = fradVal.asArray();
		fradVec.reserve(fradArr->size());
		for (const auto &fradElem : *fradArr)
			fradVec.push_back(static_cast<int>(fradElem.asInt()));
		bc.functionReturnArrayDims[fradKey.str()] = std::move(fradVec);
	}
	bc.nextVarIndex = static_cast<int>(root.getField("nextVarIndex").asInt());
	auto structsArr = root.getField("structs").asArray();
	bc.structs.reserve(structsArr->size());
	for (const auto &sv : *structsArr)
	{
		StructInfo si;
		si.name            = sv.getField("name").stl_string();
		si.firstConstIndex = static_cast<int>(sv.getField("firstConstIndex").asInt());
		si.fieldCount      = static_cast<int>(sv.getField("fieldCount").asInt());
		auto fieldNamesArr = sv.getField("fieldNames").asArray();
		si.fieldNames.reserve(fieldNamesArr->size());
		for (const auto &fnVal : *fieldNamesArr)
			si.fieldNames.push_back(fnVal.stl_string());
		auto fieldArrayDimsArr = sv.getField("fieldArrayDims").asArray();
		si.fieldArrayDims.reserve(fieldArrayDimsArr->size());
		for (const auto &dimsVal : *fieldArrayDimsArr)
		{
			std::vector<int> dims;
			auto dimsInnerArr = dimsVal.asArray();
			dims.reserve(dimsInnerArr->size());
			for (const auto &dimVal : *dimsInnerArr)
				dims.push_back(static_cast<int>(dimVal.asInt()));
			si.fieldArrayDims.push_back(std::move(dims));
		}
		auto fieldTypeNamesArr = sv.getField("fieldTypeNames").asArray();
		si.fieldTypeNames.reserve(fieldTypeNamesArr->size());
		for (const auto &ftnVal : *fieldTypeNamesArr)
			si.fieldTypeNames.push_back(ftnVal.stl_string());
		bc.structs.push_back(std::move(si));
	}
	auto structEntriesStruct = root.getField("structEntries").asStruct();
	for (const auto &[seKey, seVal] : structEntriesStruct->fields)
		bc.structEntries[seKey.str()] = static_cast<int>(seVal.asInt());
	return bc;
}
}#pragma once
#include <vector>
#include <string>
#include <unordered_set>
#include <unordered_map>
#include <phsint.hpp>
#include "../ISA/ISA.hpp"
#include <Value.hpp>
namespace Phasor
{
/** @brief Instruction with up to 3 operands
 *  Format: instruction operand1, operand2, operand3
 *  Each instruction uses only the operands it needs
 */ 
struct Instruction
{
	OpCode  op;   ///< Operation code
	i32 operand1; ///< First operand
	i32 operand2; ///< Second operand
	i32 operand3; ///< Third operand
	// Default constructor
	Instruction() : op(OpCode::HALT), operand1(0), operand2(0), operand3(0)
	{
	}
	// Full constructor
	Instruction(OpCode op, i32 op1 = 0, i32 op2 = 0, i32 op3 = 0)
	    : op(op), operand1(op1), operand2(op2), operand3(op3)
	{
	}
};
/// @brief Struct metadata stored alongside bytecode (struct section)
struct StructInfo
{
    std::string              name;
    int                      firstConstIndex;
    int                      fieldCount;
    std::vector<std::string> fieldNames;
    std::vector<std::vector<int>> fieldArrayDims;
    std::vector<std::string>      fieldTypeNames;
};
/// @brief Complete bytecode structure
struct Bytecode
{
	std::vector<Instruction>             instructions;        ///< List of instructions
	std::vector<Value>                   constants;           ///< Constant pool
	std::unordered_map<std::string, int> variables;           ///< Variable name -> index mapping
	std::vector<std::vector<std::pair<int, std::string>>> scopeVarLists; ///< Per-scope var indices to free on EXIT_SCOPE
	std::unordered_map<std::string, int> functionEntries;     ///< Function name -> instruction index mapping
	std::unordered_map<std::string, int> functionParamCounts; ///< Function name -> parameter count
	std::unordered_map<std::string, std::vector<std::string>> functionParamTypeNames; ///< Function name -> parameter type names
	std::unordered_map<std::string, std::vector<std::vector<int>>> functionParamArrayDims;
	std::unordered_map<std::string, std::string> functionReturnTypeNames; ///< Function name -> return type name
	std::unordered_map<std::string, std::vector<int>> functionReturnArrayDims; ///< Function name -> return array dims
	int                                  nextVarIndex = 0;    ///< Next available variable index
	// Struct section (planned usage by future struct codegen)
	std::vector<StructInfo>              structs;       ///< List of struct descriptors
	std::unordered_map<std::string, int> structEntries; ///< Struct name -> index in structs
	/// @brief Add a constant to the pool and return its index
	int addConstant(const Value &value)
	{
		constants.push_back(value);
		return static_cast<int>(constants.size()) - 1;
	}
	/// @brief Add a string constant with deduplication
	int addStringConstant(const std::string &s)
	{
		auto it = stringConstantCache.find(s);
		if (it != stringConstantCache.end())
		{
			return it->second;
		}
		int idx = addConstant(Value(s));
		stringConstantCache[s] = idx;
		return idx;
	}
	std::unordered_map<std::string, int> stringConstantCache; ///< Dedup cache for string constants
	/// @brief Get or create a variable index
	int getOrCreateVar(const std::string &name)
	{
		auto it = variables.find(name);
		if (it != variables.end())
		{
			return it->second;
		}
		int index = nextVarIndex++;
		variables[name] = index;
		return index;
	}
	/// @brief Emit an instruction with operands
	void emit(OpCode op, i32 op1 = 0, i32 op2 = 0, i32 op3 = 0)
	{
		instructions.emplace_back(op, op1, op2, op3);
	}
};
}#include "CodeGen.hpp"
#include <algorithm>
#include <algorithm>
#include <iostream>
#include <queue>
#include <ranges>
#include <unordered_map>
#include <unordered_set>
#include <algorithm>
#include <phsint.hpp>
namespace Phasor
{
static void collectCallsExpr(const AST::Expression *expr, std::unordered_set<std::string> &out);
static void collectCallsStmt(const AST::Statement  *stmt, std::unordered_set<std::string> &out);
static void collectCallsExpr(const AST::Expression *expr, std::unordered_set<std::string> &out)
{
	if (expr == nullptr)
	{ 
		return;
	}
	if (const auto *e = dynamic_cast<const AST::CallExpr *>(expr))
	{
		out.insert(e->callee);
		for (const auto &a : e->arguments)
		{	
			collectCallsExpr(a.get(), out);
		}
	}
	else if (const auto *e = dynamic_cast<const AST::BinaryExpr *>(expr))
	{
		collectCallsExpr(e->left.get(), out);
		collectCallsExpr(e->right.get(), out);
	}
	else if (const auto *e = dynamic_cast<const AST::UnaryExpr *>(expr))
	{
		collectCallsExpr(e->operand.get(), out);
	}
	else if (const auto *e = dynamic_cast<const AST::PostfixExpr *>(expr))
	{
		collectCallsExpr(e->operand.get(), out);
	}
	else if (const auto *e = dynamic_cast<const AST::AssignmentExpr *>(expr))
	{
		collectCallsExpr(e->target.get(), out);
		collectCallsExpr(e->value.get(), out);
	}
	else if (const auto *e = dynamic_cast<const AST::FieldAccessExpr *>(expr))
	{
		collectCallsExpr(e->object.get(), out);
	}
	else if (const auto *e = dynamic_cast<const AST::ArrayAccessExpr *>(expr))
	{
		collectCallsExpr(e->array.get(), out);
		collectCallsExpr(e->index.get(), out);
	}
	else if (const auto *e = dynamic_cast<const AST::ArrayLiteralExpr *>(expr))
	{
		for (const auto &elem : e->elements)
		{
			collectCallsExpr(elem.get(), out);
		}
	}
	else if (const auto *e = dynamic_cast<const AST::StructInstanceExpr *>(expr))
	{
		for (const auto &[fname, fval] : e->fieldValues)
		{ 
			collectCallsExpr(fval.get(), out);
		}
	}
}
static void collectCallsStmt(const AST::Statement *stmt, std::unordered_set<std::string> &out)
{
	if (stmt == nullptr){ return;
}
	if (const auto *s = dynamic_cast<const AST::BlockStmt *>(stmt))
	{
		for (const auto &inner : s->statements)
		{
			collectCallsStmt(inner.get(), out);
		}
	}
	else if (const auto *s = dynamic_cast<const AST::UnsafeBlockStmt *>(stmt))
	{
		collectCallsStmt(s->block.get(), out);
	}
	else if (const auto *s = dynamic_cast<const AST::ExpressionStmt *>(stmt))
	{
		collectCallsExpr(s->expression.get(), out);
	}
	else if (const auto *s = dynamic_cast<const AST::VarDecl *>(stmt))
	{
		collectCallsExpr(s->initializer.get(), out);
	}
	else if (const auto *s = dynamic_cast<const AST::PrintStmt *>(stmt))
	{
		collectCallsExpr(s->expression.get(), out);
	}
	else if (const auto *s = dynamic_cast<const AST::IfStmt *>(stmt))
	{
		collectCallsExpr(s->condition.get(), out);
		collectCallsStmt(s->thenBranch.get(), out);
		collectCallsStmt(s->elseBranch.get(), out);
	}
	else if (const auto *s = dynamic_cast<const AST::WhileStmt *>(stmt))
	{
		collectCallsExpr(s->condition.get(), out);
		collectCallsStmt(s->body.get(), out);
	}
	else if (const auto *s = dynamic_cast<const AST::ForStmt *>(stmt))
	{
		collectCallsStmt(s->initializer.get(), out);
		collectCallsExpr(s->condition.get(), out);
		collectCallsExpr(s->increment.get(), out);
		collectCallsStmt(s->body.get(), out);
	}
	else if (const auto *s = dynamic_cast<const AST::ReturnStmt *>(stmt))
	{
		collectCallsExpr(s->value.get(), out);
	}
	else if (const auto *s = dynamic_cast<const AST::SwitchStmt *>(stmt))
	{
		collectCallsExpr(s->expr.get(), out);
		for (const auto &c : s->cases)
		{
			collectCallsExpr(c.value.get(), out);
			for (const auto &cs : c.statements)
			{
				collectCallsStmt(cs.get(), out);
			}
		}
		for (const auto &ds : s->defaultStmts)
		{ 
			collectCallsStmt(ds.get(), out);
		}
	}
	else if (const auto *s = dynamic_cast<const AST::ExportStmt *>(stmt))
	{
		if (dynamic_cast<const AST::FunctionDecl *>(s->declaration.get()) == nullptr)
		{
			collectCallsStmt(s->declaration.get(), out);
		}
	}
}
Bytecode CodeGenerator::generate(const AST::Program &program, const std::unordered_map<std::string, int> &existingVars,
                                 int nextVarIdx, bool replMode)
{
	bytecode = Bytecode(); // Reset bytecode
	bytecode.variables = existingVars;
	bytecode.nextVarIndex = nextVarIdx;
	isRepl = replMode;
	declaredTypes.clear();
	inferredTypes.clear();
	inferredFieldTypes.clear();
	arrayDimensions.clear();
	arrayBaseTypes.clear();
	currentFunctionReturnType.clear();
	currentFunctionReturnDims.clear();
	currentFunctionHasReturn = false;
	liveFunctions.clear();
	forwardDecls.clear();
	std::unordered_map<std::string, const AST::FunctionDecl *> allFunctions;
	for (const auto &stmt : program.statements)
	{
		const auto *fd = dynamic_cast<const AST::FunctionDecl *>(stmt.get());
		if (fd == nullptr)
		{
			if (const auto *es = dynamic_cast<const AST::ExportStmt *>(stmt.get()))
			{
				fd = dynamic_cast<const AST::FunctionDecl *>(es->declaration.get());
			}
		}
		if (fd != nullptr) 
		{ 
			allFunctions[fd->name] = fd;
		}
	}
	if (!isRepl)
	{
		std::unordered_map<std::string, std::unordered_set<std::string>> callGraph;
		for (const auto &[name, fd] : allFunctions)
		{
			std::unordered_set<std::string> called;
			collectCallsStmt(fd->body.get(), called);
			callGraph[name] = std::move(called);
		}
		if (allFunctions.contains("main") != 0u)
		{
			liveFunctions.insert("main");
		}
		for (const auto &stmt : program.statements)
		{
			if (const auto *es = dynamic_cast<const AST::ExportStmt *>(stmt.get()))
			{
				if (const auto *fd = dynamic_cast<const AST::FunctionDecl *>(es->declaration.get()))
				{
					liveFunctions.insert(fd->name);
				}
			}
		}
		for (const auto &[name, fd] : allFunctions)
		{
			if (fd->keep)
			{
				liveFunctions.insert(name);
			}
		}
		for (const auto &stmt : program.statements)
		{
			bool isFuncDecl    = (dynamic_cast<const AST::FunctionDecl *>(stmt.get()) != nullptr);
			bool isExportedFn  = false;
			if (const auto *es = dynamic_cast<const AST::ExportStmt *>(stmt.get()))
			{
				isExportedFn = (dynamic_cast<const AST::FunctionDecl *>(es->declaration.get()) != nullptr);
			}
			if (!isFuncDecl && !isExportedFn)
			{
				collectCallsStmt(stmt.get(), liveFunctions);
			}
		}
		std::queue<std::string> worklist;
		for (const auto &name : liveFunctions)
		{
			worklist.push(name);
		}
		while (!worklist.empty())
		{
			std::string fn = worklist.front();
			worklist.pop();
			auto it = callGraph.find(fn);
			if (it == callGraph.end())
			{
				continue;
			}
			for (const auto &callee : it->second)
			{
				if ((allFunctions.contains(callee) != 0u) && (liveFunctions.contains(callee) == 0u))
				{
					liveFunctions.insert(callee);
					worklist.push(callee);
				}
			}
		}
#ifdef _DEBUG
		for (const auto &[name, fd] : allFunctions)
		{
			if (!liveFunctions.count(name))
			{
				std::cerr << "\033[33m" << "WARNING: " "\033[0m" << "[UNUSED-FUNCTION] function '" << name << "' is unused and will not be emitted"
				          << " (line " << fd->line << ", column " << fd->column << ")\n";
			}
		}
#endif
	}
	for (const auto &stmt : program.statements)
	{
		generateStatement(stmt.get());
	}
	for (const auto &name : forwardDecls)
	{
		if (!allFunctions.contains(name))
		{
			throw std::runtime_error("Function '" + name + "' was declared but never defined.");
		}
	}
	bytecode.emit(OpCode::HALT);
	return bytecode;
}
bool CodeGenerator::isLiteralExpression(const AST::Expression *expr, Value &outValue)
{
	if (const auto *numExpr = dynamic_cast<const AST::NumberExpr *>(expr))
	{
		try
		{
			if (numExpr->value.find('.') != std::string::npos)
			{
				outValue = Value(std::stod(numExpr->value));
			} else {
				outValue = Value(static_cast<i64>(std::stoll(numExpr->value)));
			}
			return true;
		}
		catch (...)
		{
			return false;
		}
	}
	if (const auto *strExpr = dynamic_cast<const AST::StringExpr *>(expr))
	{
		outValue = Value(strExpr->value);
		return true;
	}
	if (const auto *boolExpr = dynamic_cast<const AST::BooleanExpr *>(expr))
	{
		outValue = Value(boolExpr->value);
		return true;
	}
	if (dynamic_cast<const AST::NullExpr *>(expr) != nullptr)
	{
		outValue = Value();
		return true;
	}
	if (const auto *unaryExpr = dynamic_cast<const AST::UnaryExpr *>(expr))
	{
		Value operandVal;
		if (unaryExpr->op == AST::UnaryOp::Negate && isLiteralExpression(unaryExpr->operand.get(), operandVal))
		{
			ValueType operandType = operandVal.getType();
			if (operandType == ValueType::Int || operandType == ValueType::Float)
			{
				try
				{
					outValue = Value(static_cast<i64>(0)) - operandVal;
					return true;
				}
				catch (...)
				{
					return false;
				}
			}
			return false;
		}
		if (unaryExpr->op == AST::UnaryOp::Not && isLiteralExpression(unaryExpr->operand.get(), operandVal))
		{
			if (operandVal.isBool())
			{
				outValue = Value(!operandVal.asBool());
				return true;
			}
			return false;
		}
	}
	return false;
}
ValueType CodeGenerator::inferExpressionType(const AST::Expression *expr, bool &known)
{
	// If literal, we know the type immediately
	Value lit;
	if (isLiteralExpression(expr, lit))
	{
		known = true;
		return lit.getType();
	}
	// If identifier and we've inferred its type previously, return that
	if (const auto *ident = dynamic_cast<const AST::IdentifierExpr *>(expr))
	{
		auto it = inferredTypes.find(ident->name);
		if (it != inferredTypes.end())
		{
			known = true;
			return it->second;
		}
	}
	// Unary expression
	if (const auto *unaryExpr = dynamic_cast<const AST::UnaryExpr *>(expr))
	{
		if (unaryExpr->op == AST::UnaryOp::Not)
		{
			known = true;
			return ValueType::Bool;
		}
		if (unaryExpr->op == AST::UnaryOp::Negate)
		{
			return inferExpressionType(unaryExpr->operand.get(), known);
		}
	}
	// Binary expression
	if (const auto *binExpr = dynamic_cast<const AST::BinaryExpr *>(expr))
	{
		if (binExpr->op == AST::BinaryOp::And || binExpr->op == AST::BinaryOp::Or ||
		    binExpr->op == AST::BinaryOp::Equal || binExpr->op == AST::BinaryOp::NotEqual ||
		    binExpr->op == AST::BinaryOp::LessThan || binExpr->op == AST::BinaryOp::GreaterThan ||
		    binExpr->op == AST::BinaryOp::LessEqual || binExpr->op == AST::BinaryOp::GreaterEqual)
		{
			known = true;
			return ValueType::Bool;
		}
		bool leftKnown = false;
		bool rightKnown = false;
		ValueType leftType = inferExpressionType(binExpr->left.get(), leftKnown);
		ValueType rightType = inferExpressionType(binExpr->right.get(), rightKnown);
		if (leftKnown && rightKnown)
		{
			if (leftType == ValueType::Int && rightType == ValueType::Int)
			{
				known = true;
				return ValueType::Int;
			}
			if (leftType == ValueType::Float || rightType == ValueType::Float)
			{
				known = true;
				return ValueType::Float;
			}
			if (leftType == ValueType::String || rightType == ValueType::String)
			{
				known = true;
				return ValueType::String;
			}
		}
		else if (leftKnown)
		{
			if (leftType == ValueType::Float)
			{
				known = true;
				return ValueType::Float;
			}
		}
		else if (rightKnown)
		{
			if (rightType == ValueType::Float)
			{
				known = true;
				return ValueType::Float;
			}
		}
	}
	// Postfix expression
	if (const auto *postfixExpr = dynamic_cast<const AST::PostfixExpr *>(expr))
	{
		return inferExpressionType(postfixExpr->operand.get(), known);
	}
	// Assignment expression
	if (const auto *assignExpr = dynamic_cast<const AST::AssignmentExpr *>(expr))
	{
		return inferExpressionType(assignExpr->value.get(), known);
	}
	// Call expression
	if (const auto *callExpr = dynamic_cast<const AST::CallExpr *>(expr))
	{
		if (callExpr->callee == "len")
		{
			known = true;
			return ValueType::Int;
		}
		if (callExpr->callee == "starts_with" || callExpr->callee == "ends_with")
		{
			known = true;
			return ValueType::Bool;
		}
		auto retTypeIt = bytecode.functionReturnTypeNames.find(callExpr->callee);
		if (retTypeIt != bytecode.functionReturnTypeNames.end()) 
		{
			if (retTypeIt->second != "any") 
			{
				known = true;
				auto dimsIt = bytecode.functionReturnArrayDims.find(callExpr->callee);
				if (dimsIt != bytecode.functionReturnArrayDims.end() && !dimsIt->second.empty()) 
				{
					return ValueType::Array;
				}
				return mapTypeNameToValueType(retTypeIt->second);
			}
		}
	}
	if (dynamic_cast<const AST::ArrayLiteralExpr *>(expr) != nullptr)
	{
		known = true;
		return ValueType::Array;
	}
	if (dynamic_cast<const AST::StructInstanceExpr *>(expr) != nullptr)
	{
		known = true;
		return ValueType::Struct;
	}
	if (const auto *arrayAccess = dynamic_cast<const AST::ArrayAccessExpr *>(expr))
	{
		const AST::Expression *cursor = arrayAccess;
		size_t accessDepth = 0;
		while (const auto *currentAccess = dynamic_cast<const AST::ArrayAccessExpr *>(cursor))
		{
			++accessDepth;
			cursor = currentAccess->array.get();
		}
		if (const auto *ident = dynamic_cast<const AST::IdentifierExpr *>(cursor))
		{
			auto arrayIt = arrayBaseTypes.find(ident->name);
			auto dimIt = arrayDimensions.find(ident->name);
			if (arrayIt != arrayBaseTypes.end() && arrayIt->second != "any")
			{
				known = true;
				if (dimIt != arrayDimensions.end() && accessDepth < dimIt->second.size())
				{
					return ValueType::Array;
				}
				return mapTypeNameToValueType(arrayIt->second);
			}
		}
		else if (const auto *fieldExpr = dynamic_cast<const AST::FieldAccessExpr *>(cursor))
		{
			if (const auto *objIdent = dynamic_cast<const AST::IdentifierExpr *>(fieldExpr->object.get()))
			{
				std::string structName;
				auto declIt = declaredTypes.find(objIdent->name);
				if (declIt != declaredTypes.end())
				{
					structName = declIt->second;
				}
				for (const auto &s : bytecode.structs)
				{
					if (!structName.empty() && s.name != structName)
					{
						continue;
					}
					for (size_t i = 0; i < s.fieldNames.size(); ++i)
					{
						if (s.fieldNames[i] == fieldExpr->fieldName)
						{
							if (s.fieldTypeNames[i] == "any")
							{
								// not known
								known = false;
								return ValueType::Float; // unused: known is false
							}
							known = true;
							return mapTypeNameToValueType(s.fieldTypeNames[i]);
						}
					}
				}
			}
		}
	}
	if (const auto *fieldExpr = dynamic_cast<const AST::FieldAccessExpr *>(expr))
	{
		// field on a named variable we have field-type records for
		if (const auto *objIdent = dynamic_cast<const AST::IdentifierExpr *>(fieldExpr->object.get()))
		{
			auto varIt = inferredFieldTypes.find(objIdent->name);
			if (varIt != inferredFieldTypes.end())
			{
				auto fieldIt = varIt->second.find(fieldExpr->fieldName);
				if (fieldIt != varIt->second.end())
				{
					known = true;
					return fieldIt->second;
				}
			}
			// named struct type, need to look up StructInfo
			auto typeIt = inferredTypes.find(objIdent->name);
			if (typeIt != inferredTypes.end() && typeIt->second == ValueType::Struct)
			{
				std::string structName;
				auto declIt = declaredTypes.find(objIdent->name);
				if (declIt != declaredTypes.end())
				{
					structName = declIt->second;
				}
				for (const auto &s : bytecode.structs)
				{
					if (!structName.empty() && s.name != structName)
					{
						continue;
					}
					for (size_t i = 0; i < s.fieldNames.size(); ++i)
					{
						if (s.fieldNames[i] == fieldExpr->fieldName)
						{
							if (!s.fieldArrayDims[i].empty())
							{
								known = true;
								return ValueType::Array;
							}
							if (s.fieldTypeNames[i] == "any")
							{
								// not known
								known = false;
								return ValueType::Float;
							}
							known = true;
							return mapTypeNameToValueType(s.fieldTypeNames[i]);
						}
					}
				}
			}
		}
	}
	// Unknown
	known = false;
	return ValueType::Float;
}
void CodeGenerator::generateStatement(const AST::Statement *stmt)
{
	if (const auto *forwardDecl = dynamic_cast<const AST::ForwardDecl *>(stmt))
	{
		forwardDecls.insert(forwardDecl->name);
		return;
	}
	if (const auto *varDecl = dynamic_cast<const AST::VarDecl *>(stmt))
	{
		generateVarDecl(varDecl);
	}
	else if (const auto *exprStmt = dynamic_cast<const AST::ExpressionStmt *>(stmt))
	{
		generateExpressionStmt(exprStmt);
	}
	else if (const auto *printStmt = dynamic_cast<const AST::PrintStmt *>(stmt))
	{
		generatePrintStmt(printStmt);
	}
	else if (dynamic_cast<const AST::IncludeStmt *>(stmt) != nullptr)
	{
		// preprocessor include
	}
	else if (const auto *blockStmt = dynamic_cast<const AST::BlockStmt *>(stmt))
	{
		generateBlockStmt(blockStmt);
	}
	else if (const auto *ifStmt = dynamic_cast<const AST::IfStmt *>(stmt))
	{
		generateIfStmt(ifStmt);
	}
	else if (const auto *whileStmt = dynamic_cast<const AST::WhileStmt *>(stmt))
	{
		generateWhileStmt(whileStmt);
	}
	else if (const auto *forStmt = dynamic_cast<const AST::ForStmt *>(stmt))
	{
		generateForStmt(forStmt);
	}
	else if (const auto *returnStmt = dynamic_cast<const AST::ReturnStmt *>(stmt))
	{
		generateReturnStmt(returnStmt);
	}
	else if (const auto *unsafeStmt = dynamic_cast<const AST::UnsafeBlockStmt *>(stmt))
	{
		generateUnsafeBlockStmt(unsafeStmt);
	}
	else if (const auto *funcDecl = dynamic_cast<const AST::FunctionDecl *>(stmt))
	{
		generateFunctionDecl(funcDecl);
	}
	else if (const auto *structDecl = dynamic_cast<const AST::StructDecl *>(stmt))
	{
		generateStructDecl(structDecl);
	}
	else if (dynamic_cast<const AST::BreakStmt *>(stmt) != nullptr)
	{
		generateBreakStmt();
	}
	else if (dynamic_cast<const AST::ContinueStmt *>(stmt) != nullptr)
	{
		generateContinueStmt();
	}
	else if (const auto *switchStmt = dynamic_cast<const AST::SwitchStmt *>(stmt))
	{
		generateSwitchStmt(switchStmt);
	} else {
		throw std::runtime_error("Unknown statement type in code generation");
	}
}
void CodeGenerator::generateExpression(const AST::Expression *expr, bool resultNeeded)
{
	if (const auto *numExpr = dynamic_cast<const AST::NumberExpr *>(expr))
	{
		generateNumberExpr(numExpr);
	}
	else if (const auto *strExpr = dynamic_cast<const AST::StringExpr *>(expr))
	{
		generateStringExpr(strExpr);
	}
	else if (const auto *identExpr = dynamic_cast<const AST::IdentifierExpr *>(expr))
	{
		generateIdentifierExpr(identExpr);
	}
	else if (const auto *unaryExpr = dynamic_cast<const AST::UnaryExpr *>(expr))
	{
		generateUnaryExpr(unaryExpr);
	}
	else if (const auto *callExpr = dynamic_cast<const AST::CallExpr *>(expr))
	{
		generateCallExpr(callExpr);
	}
	else if (const auto *binExpr = dynamic_cast<const AST::BinaryExpr *>(expr))
	{
		generateBinaryExpr(binExpr);
	}
	else if (const auto *boolExpr = dynamic_cast<const AST::BooleanExpr *>(expr))
	{
		generateBooleanExpr(boolExpr);
	}
	else if (const auto *nullExpr = dynamic_cast<const AST::NullExpr *>(expr))
	{
		generateNullExpr(nullExpr);
	}
	else if (const auto *assignExpr = dynamic_cast<const AST::AssignmentExpr *>(expr))
	{
		generateAssignmentExpr(assignExpr);
	}
	else if (const auto *structExpr = dynamic_cast<const AST::StructInstanceExpr *>(expr))
	{
		generateStructInstanceExpr(structExpr);
	}
	else if (const auto *fieldAccessExpr = dynamic_cast<const AST::FieldAccessExpr *>(expr))
	{
		generateFieldAccessExpr(fieldAccessExpr);
	}
	else if (const auto *postfixExpr = dynamic_cast<const AST::PostfixExpr *>(expr))
	{
		generatePostfixExpr(postfixExpr, resultNeeded);
	}
	else if (const auto *arrayLit = dynamic_cast<const AST::ArrayLiteralExpr *>(expr))
	{
		generateArrayLiteralExpr(arrayLit, resultNeeded);
	}
	else if (const auto *arrayAccess = dynamic_cast<const AST::ArrayAccessExpr *>(expr))
	{
		generateArrayAccessExpr(arrayAccess, resultNeeded);
	} else {
		throw std::runtime_error("Unknown expression type in code generation");
	}
}
void CodeGenerator::generateVarDecl(const AST::VarDecl *varDecl)
{
	bool hasExplicitType = (varDecl->type != nullptr);
	bool isAny = (hasExplicitType && varDecl->type->name == "any");
	bool isArrayType = (hasExplicitType && !varDecl->type->arrayDimensions.empty());
	// default to null, not float
	ValueType declaredType = ValueType::Null;
	if (hasExplicitType)
	{
		declaredTypes[varDecl->name] = varDecl->type->name;
		if (isAny)
		{
			if (isArrayType)
			{
				arrayBaseTypes[varDecl->name] = "any";
			}
			if (varDecl->initializer)
			{
				bool known = false;
				ValueType inferred = inferExpressionType(varDecl->initializer.get(), known);
				if (known)
				{
					inferredTypes[varDecl->name] = inferred;
				}
				if (const auto *structExpr = dynamic_cast<const AST::StructInstanceExpr *>(varDecl->initializer.get()))
				{
					inferredTypes[varDecl->name] = ValueType::Struct;
					for (const auto &[fieldName, fieldValue] : structExpr->fieldValues)
					{
						bool fKnown = false;
						ValueType fType = inferExpressionType(fieldValue.get(), fKnown);
						if (fKnown)
						{
							inferredFieldTypes[varDecl->name][fieldName] = fType;
						}
					}
				}
			}
		}
		else if (isArrayType)
		{
			arrayBaseTypes[varDecl->name] = varDecl->type->name;
			arrayDimensions[varDecl->name] = varDecl->type->arrayDimensions;
			declaredType = ValueType::Array;
			inferredTypes[varDecl->name] = declaredType;
		}
		else if (bytecode.structEntries.contains(varDecl->type->name))
		{
			declaredType = ValueType::Struct;
			inferredTypes[varDecl->name] = declaredType;
		} else {
			declaredType = mapTypeNameToValueType(varDecl->type->name);
			inferredTypes[varDecl->name] = declaredType;
		}
	}
	auto declareVar = [&](const std::string &name) -> int {
		if (!scopeStack.empty())
		{
			ScopeFrame &frame = scopeStack.back();
			auto existing = bytecode.variables.find(name);
			if (!frame.savedBindings.contains(name))
			{
				frame.savedBindings[name] = (existing != bytecode.variables.end())
												? existing->second : -1;
			}
			if (!frame.savedInferredTypes.contains(name))
			{
				auto it = inferredTypes.find(name);
				frame.savedInferredTypes[name] = (it != inferredTypes.end())
													? std::optional<ValueType>(it->second)
													: std::nullopt;
			}
			if (!frame.savedArrayBaseTypes.contains(name))
			{
				auto it = arrayBaseTypes.find(name);
				frame.savedArrayBaseTypes[name] = (it != arrayBaseTypes.end())
													? std::optional<std::string>(it->second)
													: std::nullopt;
			}
			if (!frame.savedArrayDimensions.contains(name))
			{
				auto it = arrayDimensions.find(name);
				frame.savedArrayDimensions[name] = (it != arrayDimensions.end())
													? std::optional<std::vector<int>>(it->second)
													: std::nullopt;
			}
			if (!frame.savedDeclaredTypes.contains(name))
			{
				auto it = declaredTypes.find(name);
				frame.savedDeclaredTypes[name] = (it != declaredTypes.end())
													? std::optional<std::string>(it->second)
													: std::nullopt;
			}
			int idx = bytecode.nextVarIndex++;
			bytecode.variables[name] = idx;
			frame.declaredIndices.emplace_back(idx, name);
			return idx;
		}
		return bytecode.getOrCreateVar(name);
	};
	if (varDecl->initializer)
	{
		const auto *arrayLit = dynamic_cast<const AST::ArrayLiteralExpr *>(varDecl->initializer.get());
		if (hasExplicitType && !isAny)
		{
			if (!isArrayType && (arrayLit != nullptr))
			{
				throw std::runtime_error("Variable '" + varDecl->name +
				                         "' is declared as a scalar type but assigned an array literal.");
			}
			if (isArrayType && (arrayLit != nullptr))
			{
				if (!varDecl->type->arrayDimensions.empty() && varDecl->type->arrayDimensions[0] != -1)
				{
					if (arrayLit->elements.size() != static_cast<size_t>(varDecl->type->arrayDimensions[0]))
					{
						throw std::runtime_error("Array bounds error: variable '" + varDecl->name +
                                                 "' expects " + std::to_string(varDecl->type->arrayDimensions[0]) +
                                                 " elements, but got " + std::to_string(arrayLit->elements.size()));
					}
				}
				if (bytecode.structEntries.contains(varDecl->type->name))
				{
					const std::string &expectedStruct = varDecl->type->name;
					auto expectedIt = bytecode.structEntries.find(expectedStruct);
					const StructInfo &expectedInfo = bytecode.structs[expectedIt->second];
					for (const auto & element : arrayLit->elements)
					{
						auto *structExpr = dynamic_cast<AST::StructInstanceExpr *>(element.get());
						if (structExpr == nullptr)
						{ 
							continue;
						}
						if (structExpr->structName != "__anon" && structExpr->structName != expectedStruct)
						{
							throw std::runtime_error("Array element has wrong struct type: expected '" +
							                         expectedStruct + "', got '" + structExpr->structName + "'");
						}
						if (structExpr->structName == "__anon")
						{
							if (structExpr->fieldValues.size() != expectedInfo.fieldNames.size())
							{
								throw std::runtime_error("Field count mismatch for struct '" + expectedStruct + "'");
							}
							for (const auto &[fname, fval] : structExpr->fieldValues)
							{
								if (std::ranges::find(expectedInfo.fieldNames, fname) ==
								    expectedInfo.fieldNames.end())
								{
									throw std::runtime_error("Unknown field '" + fname + "' in struct '" + expectedStruct + "'");
								}
							}
						}
					}
				}
				if (!bytecode.structEntries.contains(varDecl->type->name))
				{
					bool isMultiDim = varDecl->type->arrayDimensions.size() > 1;
					ValueType expectedElemType = isMultiDim
						? ValueType::Array
						: mapTypeNameToValueType(varDecl->type->name);
					for (size_t i = 0; i < arrayLit->elements.size(); ++i)
					{
						bool known = false;
						ValueType elemType = inferExpressionType(arrayLit->elements[i].get(), known);
						if (known && elemType != expectedElemType)
						{
							throw std::runtime_error("Type mismatch in array initialization: element at index " +
													std::to_string(i) + " is not of expected type '" +
													varDecl->type->name + "'.");
						}
					}
				}
			}
		}
		if (const auto *binExpr = dynamic_cast<const AST::BinaryExpr *>(varDecl->initializer.get()))
		{
			generateBinaryExpr(binExpr, declaredType);
		} else {
			generateExpression(varDecl->initializer.get(), true);
		}
		int varIndex = declareVar(varDecl->name);
		bytecode.emit(OpCode::STORE_VAR, varIndex);
	} else {
		if (isArrayType)
		{
			// Automatically generate bytecode to instantiate default arrays
			generateDefaultArray(varDecl->type->arrayDimensions, 0, varDecl->type->name);
		} else {
			// Keep standard default scalar initialization (null)
			int constIndex = bytecode.addConstant(Value());
			bytecode.emit(OpCode::PUSH_CONST, constIndex);
		}
		int varIndex = declareVar(varDecl->name);
		bytecode.emit(OpCode::STORE_VAR, varIndex);
	}
}
void CodeGenerator::generateExpressionStmt(const AST::ExpressionStmt *exprStmt)
{
	if (isRepl)
	{
		generateExpression(exprStmt->expression.get(), true);
		bytecode.emit(OpCode::PRINT);
		return;
	}
	if (const auto *postfix = dynamic_cast<const AST::PostfixExpr *>(exprStmt->expression.get()))
	{
		generatePostfixExpr(postfix, false);
	} else {
		generateExpression(exprStmt->expression.get());
		bytecode.emit(OpCode::POP);
	}
}
void CodeGenerator::generatePrintStmt(const AST::PrintStmt *printStmt)
{
	generateExpression(printStmt->expression.get());
	bytecode.emit(OpCode::PRINT);
}
void CodeGenerator::generateExportStmt(const AST::ExportStmt *exportStmt)
{
	generateStatement(exportStmt->declaration.get());
}
void CodeGenerator::generateNumberExpr(const AST::NumberExpr *numExpr)
{
	try
	{
		if (numExpr->value.find('.') != std::string::npos)
		{
			f64 d = std::stod(numExpr->value);
			int constIndex = bytecode.addConstant(Value(d));
			bytecode.emit(OpCode::PUSH_CONST, constIndex);
		} else {
			i64 i = std::stoll(numExpr->value);
			int     constIndex = bytecode.addConstant(Value(i));
			bytecode.emit(OpCode::PUSH_CONST, constIndex);
		}
	}
	catch (...)
	{
		throw std::runtime_error("Invalid number format: " + numExpr->value);
	}
}
void CodeGenerator::generateStringExpr(const AST::StringExpr *strExpr)
{
	int constIndex = bytecode.addConstant(Value(strExpr->value));
	bytecode.emit(OpCode::PUSH_CONST, constIndex);
}
void CodeGenerator::generateIdentifierExpr(const AST::IdentifierExpr *identExpr)
{
	int varIndex = bytecode.getOrCreateVar(identExpr->name);
	bytecode.emit(OpCode::LOAD_VAR, varIndex);
}
void CodeGenerator::generateUnaryExpr(const AST::UnaryExpr *unaryExpr)
{
	// fold literal unary
	Value folded;
	if (isLiteralExpression(unaryExpr, folded))
	{
		if (folded.isBool())
		{
			bytecode.emit(folded.asBool() ? OpCode::TRUE_P : OpCode::FALSE_P);
		}
		else if (folded.isNull())
		{
			bytecode.emit(OpCode::NULL_VAL);
		} else {
			int constIndex = bytecode.addConstant(folded);
			bytecode.emit(OpCode::PUSH_CONST, constIndex);
		}
		return;
	}
	generateExpression(unaryExpr->operand.get());
	switch (unaryExpr->op)
	{
	case AST::UnaryOp::Negate:
		bytecode.emit(OpCode::NEGATE);
		break;
	case AST::UnaryOp::Not:
		bytecode.emit(OpCode::NOT);
		break;
	case AST::UnaryOp::AddressOf:
		throw std::runtime_error("Address of not supported");
	case AST::UnaryOp::Dereference:
		throw std::runtime_error("Dereference not supported");
	}
}
void CodeGenerator::generateCallExpr(const AST::CallExpr *callExpr)
{
	if (callExpr->callee == "len" && callExpr->arguments.size() == 1)
	{
		if (const auto *strExpr = dynamic_cast<const AST::StringExpr *>(callExpr->arguments[0].get()))
		{
			auto len = (i64)strExpr->value.length();
			int  constIndex = bytecode.addConstant(Value(len));
			bytecode.emit(OpCode::PUSH_CONST, constIndex);
			return;
		}
		generateExpression(callExpr->arguments[0].get());
		bytecode.emit(OpCode::LEN);
		return;
	}
	if (callExpr->callee == "substr" && callExpr->arguments.size() == 3)
	{
		if (const auto *numExpr = dynamic_cast<const AST::NumberExpr *>(callExpr->arguments[2].get()))
		{
			if (numExpr->value == "1" || numExpr->value == "1.0")
			{
				generateExpression(callExpr->arguments[0].get());
				generateExpression(callExpr->arguments[1].get());
				bytecode.emit(OpCode::CHAR_AT);
				return;
			}
		}
	}
	if (callExpr->callee == "char_at" && callExpr->arguments.size() == 2)
	{
		generateExpression(callExpr->arguments[0].get());
		generateExpression(callExpr->arguments[1].get());
		bytecode.emit(OpCode::CHAR_AT);
		return;
	}
	if (callExpr->callee == "starts_with" && callExpr->arguments.size() == 2)
	{
		const auto *s = dynamic_cast<const AST::StringExpr *>(callExpr->arguments[0].get());
		const auto *p = dynamic_cast<const AST::StringExpr *>(callExpr->arguments[1].get());
		if ((s != nullptr) && (p != nullptr))
		{
			bool result = s->value.length() >= p->value.length() && s->value.starts_with(p->value);
			bytecode.emit(result ? OpCode::TRUE_P : OpCode::FALSE_P);
			return;
		}
	}
	if (callExpr->callee == "ends_with" && callExpr->arguments.size() == 2)
	{
		const auto *s = dynamic_cast<const AST::StringExpr *>(callExpr->arguments[0].get());
		const auto *suffix = dynamic_cast<const AST::StringExpr *>(callExpr->arguments[1].get());
		if ((s != nullptr) && (suffix != nullptr))
		{
			bool result = s->value.length() >= suffix->value.length() && s->value.ends_with(suffix->value);
			bytecode.emit(result ? OpCode::TRUE_P : OpCode::FALSE_P);
			return;
		}
	}
	for (const auto &arg : callExpr->arguments)
	{
		generateExpression(arg.get());
	}
	int constIndex = bytecode.addConstant(Value(static_cast<i64>(callExpr->arguments.size())));
	bytecode.emit(OpCode::PUSH_CONST, constIndex);
	bool isUserFunction = (bytecode.functionEntries.contains(callExpr->callee)) || 
	                      (forwardDecls.contains(callExpr->callee));
	if (isUserFunction)
	{
		int nameIndex = bytecode.addStringConstant(callExpr->callee);
		auto itParam = bytecode.functionParamCounts.find(callExpr->callee);
		if (itParam != bytecode.functionParamCounts.end())
		{
			int expected = itParam->second;
			int got = static_cast<int>(callExpr->arguments.size());
			if (expected != got)
			{
				throw std::runtime_error("Calling function '" + callExpr->callee + "' with " + std::to_string(got)
				          + " arguments but it expects " + std::to_string(expected) + "\n");
			}
		}
		auto typeIt = bytecode.functionParamTypeNames.find(callExpr->callee);
		if (typeIt != bytecode.functionParamTypeNames.end())
		{
			const auto &paramTypes = typeIt->second;
			for (size_t i = 0; i < callExpr->arguments.size() && i < paramTypes.size(); ++i)
			{
				const std::string &expectedTypeName = paramTypes[i];
				if (expectedTypeName == "any")
				{
					continue;
				}
				bool      known   = false;
				ValueType argType = inferExpressionType(callExpr->arguments[i].get(), known);
				if (!known)
				{
					continue;
				}
				if (argType == ValueType::Array)
				{
					auto dimsIt = bytecode.functionParamArrayDims.find(callExpr->callee);
					if (dimsIt != bytecode.functionParamArrayDims.end() && i < dimsIt->second.size())
					{
						const auto &expectedDims = dimsIt->second[i];
						if (expectedDims.empty())
						{
							throw std::runtime_error("Argument " + std::to_string(i + 1) + " to '" + callExpr->callee
							          + "' expects scalar '" + expectedTypeName + "', got array (line "
							          + std::to_string(callExpr->line) + ", column " + std::to_string(callExpr->column) + ").\n");
						}
						if (expectedDims[0] != -1)
						{
							if (const auto *arrayLit = dynamic_cast<const AST::ArrayLiteralExpr *>(callExpr->arguments[i].get()))
							{
								if (arrayLit->elements.size() != static_cast<size_t>(expectedDims[0]))
								{
									throw std::runtime_error("Argument " + std::to_string(i + 1) + " to '" + callExpr->callee
									          + "' has wrong size: expected " + std::to_string(expectedDims[0])
									          + " elements, got " + std::to_string(arrayLit->elements.size())
									          + " (line " + std::to_string(callExpr->line) + ", column " + std::to_string(callExpr->column) + ").\n");
								}
							}
						}
					}
					continue;
				} else {
					auto dimsIt = bytecode.functionParamArrayDims.find(callExpr->callee);
					if (dimsIt != bytecode.functionParamArrayDims.end() && i < dimsIt->second.size())
					{
						const auto &expectedDims = dimsIt->second[i];
						if (!expectedDims.empty())
						{
							throw std::runtime_error("Argument " + std::to_string(i + 1) + " to '" + callExpr->callee
							          + "' expects array, got scalar (line " + std::to_string(callExpr->line) + ", column " + std::to_string(callExpr->column) + ").\n");
						}
					}
				}
				ValueType expectedType = mapTypeNameToValueType(expectedTypeName);
				if (argType != expectedType && expectedType != ValueType::Struct)
				{
					throw std::runtime_error("Argument " + std::to_string(i + 1) + " to '" + callExpr->callee
					          + "' has wrong type: expected '" + expectedTypeName
					          + "' (line " + std::to_string(callExpr->line) + ", column " + std::to_string(callExpr->column) + ").\n");
				}
			}
		}
		bytecode.emit(OpCode::CALL, nameIndex);
	} else {
		int nameIndex = bytecode.addStringConstant(callExpr->callee);
		bytecode.emit(OpCode::CALL_NATIVE, nameIndex);
	}
}
void CodeGenerator::generateBinaryExpr(const AST::BinaryExpr *binExpr, ValueType hint)
{
	Value leftVal;
	Value rightVal;
	if (isLiteralExpression(binExpr->left.get(), leftVal) && isLiteralExpression(binExpr->right.get(), rightVal))
	{
		try
		{
			Value result;
			switch (binExpr->op)
			{
			case AST::BinaryOp::Add:
				result = leftVal + rightVal;
				break;
			case AST::BinaryOp::Subtract:
				result = leftVal - rightVal;
				break;
			case AST::BinaryOp::Multiply:
				result = leftVal * rightVal;
				break;
			case AST::BinaryOp::Divide:
				result = leftVal / rightVal;
				break;
			case AST::BinaryOp::Modulo:
				result = leftVal % rightVal;
				break;
			case AST::BinaryOp::And:
				result = leftVal.logicalAnd(rightVal);
				break;
			case AST::BinaryOp::Or:
				result = leftVal.logicalOr(rightVal);
				break;
			case AST::BinaryOp::Equal:
				result = Value(leftVal == rightVal);
				break;
			case AST::BinaryOp::NotEqual:
				result = Value(leftVal != rightVal);
				break;
			case AST::BinaryOp::LessThan:
				result = Value(leftVal < rightVal);
				break;
			case AST::BinaryOp::GreaterThan:
				result = Value(leftVal > rightVal);
				break;
			case AST::BinaryOp::LessEqual:
				result = Value(leftVal <= rightVal);
				break;
			case AST::BinaryOp::GreaterEqual:
				result = Value(leftVal >= rightVal);
				break;
			}
			if (result.isBool())
			{
				if (result.asBool())
				{
					bytecode.emit(OpCode::TRUE_P);
				} else {
					bytecode.emit(OpCode::FALSE_P);
				}
			} else if (result.isNull())
			{
				bytecode.emit(OpCode::NULL_VAL);
			} else {
				int constIndex = bytecode.addConstant(result);
				bytecode.emit(OpCode::PUSH_CONST, constIndex);
			}
			return;
		}
		catch (...)
		{
			std::cerr << "Unknown error in Phasor::CodeGenerator::generateBinaryExpr().\n";
		}
	}
	if (binExpr->op == AST::BinaryOp::And)
	{
		generateExpression(binExpr->left.get());
		int jumpToFalseIndex = static_cast<int>(bytecode.instructions.size());
		bytecode.emit(OpCode::JUMP_IF_FALSE, 0);
		generateExpression(binExpr->right.get());
		int jumpToEndIndex = static_cast<int>(bytecode.instructions.size());
		bytecode.emit(OpCode::JUMP, 0);
		bytecode.instructions[jumpToFalseIndex].operand1 = static_cast<int>(bytecode.instructions.size());
		bytecode.emit(OpCode::FALSE_P);
		bytecode.instructions[jumpToEndIndex].operand1 = static_cast<int>(bytecode.instructions.size());
		return;
	}
	if (binExpr->op == AST::BinaryOp::Or)
	{
		generateExpression(binExpr->left.get());
		int jumpToTrueIndex = static_cast<int>(bytecode.instructions.size());
		bytecode.emit(OpCode::JUMP_IF_TRUE, 0);
		generateExpression(binExpr->right.get());
		int jumpToEndIndex = static_cast<int>(bytecode.instructions.size());
		bytecode.emit(OpCode::JUMP, 0);
		bytecode.instructions[jumpToTrueIndex].operand1 = static_cast<int>(bytecode.instructions.size());
		bytecode.emit(OpCode::TRUE_P);
		bytecode.instructions[jumpToEndIndex].operand1 = static_cast<int>(bytecode.instructions.size());
		return;
	}
	u8 rLeft = allocateRegister();
	u8 rRight = allocateRegister();
	u8 rResult = allocateRegister();
	Value leftLiteral;
	bool  leftIsLiteral = isLiteralExpression(binExpr->left.get(), leftLiteral);
	if (leftIsLiteral)
	{
		int constIndex = bytecode.addConstant(leftLiteral);
		bytecode.emit(OpCode::LOAD_CONST_R, rLeft, constIndex);
	} else {
		generateExpression(binExpr->left.get());
		bytecode.emit(OpCode::POP_R, rLeft);
	}
	Value rightLiteral;
	bool  rightIsLiteral = isLiteralExpression(binExpr->right.get(), rightLiteral);
	if (rightIsLiteral)
	{
		int constIndex = bytecode.addConstant(rightLiteral);
		bytecode.emit(OpCode::LOAD_CONST_R, rRight, constIndex);
	} else {
		generateExpression(binExpr->right.get());
		bytecode.emit(OpCode::POP_R, rRight);
	}
	auto exprIsKnownInt = [&](const AST::Expression *e, bool isLiteral, const Value &lit) -> bool {
		if (isLiteral)
		{
			return lit.isInt();
		}
		bool known = false;
		ValueType type = inferExpressionType(e, known);
		return known && type == ValueType::Int;
	};
	bool leftKnownInt  = exprIsKnownInt(binExpr->left.get(), leftIsLiteral, leftLiteral);
	bool rightKnownInt = exprIsKnownInt(binExpr->right.get(), rightIsLiteral, rightLiteral);
	bool leftKnownArray = false;
	bool rightKnownArray = false;
	if (!leftIsLiteral)
	{
		bool leftKnown = false;
		ValueType leftType = inferExpressionType(binExpr->left.get(), leftKnown);
		leftKnownArray = leftKnown && leftType == ValueType::Array;
	}
	if (!rightIsLiteral)
	{
		bool rightKnown = false;
		ValueType rightType = inferExpressionType(binExpr->right.get(), rightKnown);
		rightKnownArray = rightKnown && rightType == ValueType::Array;
	}
	if (leftKnownArray && rightKnownArray)
	{
		switch (binExpr->op)
		{
		case AST::BinaryOp::Add:
			bytecode.emit(OpCode::MADD_R, rResult, rLeft, rRight);
			break;
		case AST::BinaryOp::Subtract:
			bytecode.emit(OpCode::MSUB_R, rResult, rLeft, rRight);
			break;
		case AST::BinaryOp::Multiply:
			bytecode.emit(OpCode::MMUL_R, rResult, rLeft, rRight);
			break;
		case AST::BinaryOp::Divide:
			bytecode.emit(OpCode::MDIV_R, rResult, rLeft, rRight);
			break;
		default:
			throw std::runtime_error("Unsupported array operation");
		}
	}
	else if (leftKnownInt && rightKnownInt && hint != ValueType::Float)
	{
		switch (binExpr->op)
		{
		case AST::BinaryOp::Add:
			bytecode.emit(OpCode::IADD_R, rResult, rLeft, rRight);
			break;
		case AST::BinaryOp::Subtract:
			bytecode.emit(OpCode::ISUB_R, rResult, rLeft, rRight);
			break;
		case AST::BinaryOp::Multiply:
			bytecode.emit(OpCode::IMUL_R, rResult, rLeft, rRight);
			break;
		case AST::BinaryOp::Divide:
			bytecode.emit(OpCode::IDIV_R, rResult, rLeft, rRight);
			break;
		case AST::BinaryOp::Modulo:
			bytecode.emit(OpCode::IMOD_R, rResult, rLeft, rRight);
			break;
		case AST::BinaryOp::And:
			bytecode.emit(OpCode::IAND_R, rResult, rLeft, rRight);
			break;
		case AST::BinaryOp::Or:
			bytecode.emit(OpCode::IOR_R, rResult, rLeft, rRight);
			break;
		case AST::BinaryOp::Equal:
			bytecode.emit(OpCode::IEQ_R, rResult, rLeft, rRight);
			break;
		case AST::BinaryOp::NotEqual:
			bytecode.emit(OpCode::INE_R, rResult, rLeft, rRight);
			break;
		case AST::BinaryOp::LessThan:
			bytecode.emit(OpCode::ILT_R, rResult, rLeft, rRight);
			break;
		case AST::BinaryOp::GreaterThan:
			bytecode.emit(OpCode::IGT_R, rResult, rLeft, rRight);
			break;
		case AST::BinaryOp::LessEqual:
			bytecode.emit(OpCode::ILE_R, rResult, rLeft, rRight);
			break;
		case AST::BinaryOp::GreaterEqual:
			bytecode.emit(OpCode::IGE_R, rResult, rLeft, rRight);
			break;
		}
	} else {
		switch (binExpr->op)
		{
		case AST::BinaryOp::Add:
			bytecode.emit(OpCode::FLADD_R, rResult, rLeft, rRight);
			break;
		case AST::BinaryOp::Subtract:
			bytecode.emit(OpCode::FLSUB_R, rResult, rLeft, rRight);
			break;
		case AST::BinaryOp::Multiply:
			bytecode.emit(OpCode::FLMUL_R, rResult, rLeft, rRight);
			break;
		case AST::BinaryOp::Divide:
			bytecode.emit(OpCode::FLDIV_R, rResult, rLeft, rRight);
			break;
		case AST::BinaryOp::Modulo:
			bytecode.emit(OpCode::FLMOD_R, rResult, rLeft, rRight);
			break;
		case AST::BinaryOp::And:
			bytecode.emit(OpCode::FLAND_R, rResult, rLeft, rRight);
			break;
		case AST::BinaryOp::Or:
			bytecode.emit(OpCode::FLOR_R, rResult, rLeft, rRight);
			break;
		case AST::BinaryOp::Equal:
			bytecode.emit(OpCode::FLEQ_R, rResult, rLeft, rRight);
			break;
		case AST::BinaryOp::NotEqual:
			bytecode.emit(OpCode::FLNE_R, rResult, rLeft, rRight);
			break;
		case AST::BinaryOp::LessThan:
			bytecode.emit(OpCode::FLLT_R, rResult, rLeft, rRight);
			break;
		case AST::BinaryOp::GreaterThan:
			bytecode.emit(OpCode::FLGT_R, rResult, rLeft, rRight);
			break;
		case AST::BinaryOp::LessEqual:
			bytecode.emit(OpCode::FLLE_R, rResult, rLeft, rRight);
			break;
		case AST::BinaryOp::GreaterEqual:
			bytecode.emit(OpCode::FLGE_R, rResult, rLeft, rRight);
			break;
		}
	}
	freeRegister(rLeft);
	freeRegister(rRight);
	bytecode.emit(OpCode::PUSH_R, rResult);
	freeRegister(rResult);
}
void CodeGenerator::generateBlockStmt(const AST::BlockStmt *blockStmt)
{
    scopeStack.push_back({});
    for (const auto &stmt : blockStmt->statements)
	{
        generateStatement(stmt.get());
	}
    ScopeFrame &frame = scopeStack.back();
    for (auto &[name, oldIdx] : frame.savedBindings)
    {
        if (oldIdx == -1)
		{
            bytecode.variables.erase(name);
        } else {
            bytecode.variables[name] = oldIdx;
		}
    }
    for (auto &[name, oldType] : frame.savedInferredTypes)
    {
        if (!oldType.has_value())
		{
            inferredTypes.erase(name);
        } else {
            inferredTypes[name] = *oldType;
		}
    }
    for (auto &[name, oldBase] : frame.savedArrayBaseTypes)
    {
        if (!oldBase.has_value())
		{
            arrayBaseTypes.erase(name);
        } else {
            arrayBaseTypes[name] = *oldBase;
		}
    }
    for (auto &[name, oldDims] : frame.savedArrayDimensions)
    {
        if (!oldDims.has_value())
		{
            arrayDimensions.erase(name);
        } else {
            arrayDimensions[name] = *oldDims;
		}
    }
    for (auto &[name, oldDeclType] : frame.savedDeclaredTypes)
    {
        if (!oldDeclType.has_value())
		{
            declaredTypes.erase(name);
        } else {
            declaredTypes[name] = *oldDeclType;
		}
    }
    if (!frame.declaredIndices.empty())
    {
        int scopeId = static_cast<int>(bytecode.scopeVarLists.size());
        bytecode.scopeVarLists.push_back(frame.declaredIndices);
        bytecode.emit(OpCode::EXIT_SCOPE, scopeId);
    }
    scopeStack.pop_back();
}
void CodeGenerator::generateIfStmt(const AST::IfStmt *ifStmt)
{
	generateExpression(ifStmt->condition.get());
	int jumpToElseIndex = static_cast<int>(bytecode.instructions.size());
	bytecode.emit(OpCode::JUMP_IF_FALSE, 0);
	generateStatement(ifStmt->thenBranch.get());
	if (ifStmt->elseBranch)
	{
		int jumpToEndIndex = static_cast<int>(bytecode.instructions.size());
		bytecode.emit(OpCode::JUMP, 0);
		bytecode.instructions[jumpToElseIndex].operand1 = static_cast<int>(bytecode.instructions.size());
		generateStatement(ifStmt->elseBranch.get());
		bytecode.instructions[jumpToEndIndex].operand1 = static_cast<int>(bytecode.instructions.size());
	} else {
		bytecode.instructions[jumpToElseIndex].operand1 = static_cast<int>(bytecode.instructions.size());
	}
}
void CodeGenerator::generateWhileStmt(const AST::WhileStmt *whileStmt)
{
	int loopStartIndex = static_cast<int>(bytecode.instructions.size());
	loopStartStack.push_back(loopStartIndex);
	breakJumpsStack.emplace_back();
	continueJumpsStack.emplace_back();
	generateExpression(whileStmt->condition.get());
	int jumpToEndIndex = static_cast<int>(bytecode.instructions.size());
	bytecode.emit(OpCode::JUMP_IF_FALSE, 0);
	generateStatement(whileStmt->body.get());
	for (int continueJump : continueJumpsStack.back())
	{
		bytecode.instructions[continueJump].operand1 = loopStartIndex;
	}
	bytecode.emit(OpCode::JUMP_BACK, loopStartIndex);
	int endIndex = static_cast<int>(bytecode.instructions.size());
	bytecode.instructions[jumpToEndIndex].operand1 = endIndex;
	for (int breakJump : breakJumpsStack.back())
	{
		bytecode.instructions[breakJump].operand1 = endIndex;
	}
	loopStartStack.pop_back();
	breakJumpsStack.pop_back();
	continueJumpsStack.pop_back();
}
void CodeGenerator::generateForStmt(const AST::ForStmt *forStmt)
{
	if (forStmt->initializer)
	{
		generateStatement(forStmt->initializer.get());
	}
	int loopStartIndex = static_cast<int>(bytecode.instructions.size());
	loopStartStack.push_back(loopStartIndex);
	breakJumpsStack.emplace_back();
	continueJumpsStack.emplace_back();
	int jumpToEndIndex = -1;
	if (forStmt->condition)
	{
		generateExpression(forStmt->condition.get());
		jumpToEndIndex = static_cast<int>(bytecode.instructions.size());
		bytecode.emit(OpCode::JUMP_IF_FALSE, 0);
	}
	generateStatement(forStmt->body.get());
	int incrementIndex = static_cast<int>(bytecode.instructions.size());
	for (int continueJump : continueJumpsStack.back())
	{
		bytecode.instructions[continueJump].operand1 = incrementIndex;
	}
	if (forStmt->increment)
	{
		if (const auto *postfix = dynamic_cast<const AST::PostfixExpr *>(forStmt->increment.get()))
		{
			generatePostfixExpr(postfix, false);
		} else {
			generateExpression(forStmt->increment.get());
			bytecode.emit(OpCode::POP);
		}
	}
	bytecode.emit(OpCode::JUMP_BACK, loopStartIndex);
	int endIndex = static_cast<int>(bytecode.instructions.size());
	if (jumpToEndIndex != -1)
	{
		bytecode.instructions[jumpToEndIndex].operand1 = endIndex;
	}
	for (int breakJump : breakJumpsStack.back())
	{
		bytecode.instructions[breakJump].operand1 = endIndex;
	}
	loopStartStack.pop_back();
	breakJumpsStack.pop_back();
	continueJumpsStack.pop_back();
}
void CodeGenerator::generateBreakStmt()
{
	if (breakJumpsStack.empty())
	{
		throw std::runtime_error("'break' statement outside of loop");
	}
	int jumpIndex = static_cast<int>(bytecode.instructions.size());
	bytecode.emit(OpCode::JUMP, 0);
	breakJumpsStack.back().push_back(jumpIndex);
}
void CodeGenerator::generateContinueStmt()
{
	if (continueJumpsStack.empty())
	{
		throw std::runtime_error("'continue' statement outside of loop");
	}
	int jumpIndex = static_cast<int>(bytecode.instructions.size());
	bytecode.emit(OpCode::JUMP, 0);
	continueJumpsStack.back().push_back(jumpIndex);
}
void CodeGenerator::generateReturnStmt(const AST::ReturnStmt *returnStmt)
{
	currentFunctionHasReturn = true;
	if (returnStmt->value)
	{
		if (!currentFunctionReturnType.empty() &&
		    currentFunctionReturnType != "any"  &&
		    currentFunctionReturnType != "void")
		{
			bool      known   = false;
			ValueType retType = inferExpressionType(returnStmt->value.get(), known);
			if (known)
			{
				bool expectedIsArray = !currentFunctionReturnDims.empty();
				if (retType == ValueType::Array && !expectedIsArray)
				{
					throw std::runtime_error("Return type mismatch: function declared to return scalar '"
					          + currentFunctionReturnType + "' but returning array"
					          + " (line " + std::to_string(returnStmt->line) + ", column " + std::to_string(returnStmt->column) + ").\n");
				}
				if (retType != ValueType::Array && expectedIsArray)
				{
					throw std::runtime_error("Return type mismatch: function declared to return array '"
					          + currentFunctionReturnType + "[]' but returning scalar"
					          + " (line " + std::to_string(returnStmt->line) + ", column " + std::to_string(returnStmt->column) + ").\n");
				}
				else if (!expectedIsArray)
				{
					ValueType expectedType = mapTypeNameToValueType(currentFunctionReturnType);
					if (retType != expectedType && expectedType != ValueType::Struct)
					{
						throw std::runtime_error("Return type mismatch: function declared to return '"
						          + currentFunctionReturnType + "' but returning a different type"
						          + " (line " + std::to_string(returnStmt->line) + ", column " + std::to_string(returnStmt->column) + ").\n");
					}
				}
			}
		}
		generateExpression(returnStmt->value.get());
	} else {
		if (!currentFunctionReturnType.empty() &&
		    currentFunctionReturnType != "any"  &&
		    currentFunctionReturnType != "void")
		{
			throw std::runtime_error("Bare 'return' in function declared to return '"
			          + currentFunctionReturnType + "'"
			          + " (line " + std::to_string(returnStmt->line) + ", column " + std::to_string(returnStmt->column) + ").\n");
		}
		bytecode.emit(OpCode::NULL_VAL);
	}
	bytecode.emit(OpCode::RETURN);
}
void CodeGenerator::generateUnsafeBlockStmt(const AST::UnsafeBlockStmt *unsafeStmt)
{
	generateBlockStmt(unsafeStmt->block.get());
}
void CodeGenerator::generateFunctionDecl(const AST::FunctionDecl *funcDecl)
{
	if (!isRepl && (liveFunctions.contains(funcDecl->name) == 0u))
	{
		return;
	}
	int jumpOverIndex = static_cast<int>(bytecode.instructions.size());
	bytecode.emit(OpCode::JUMP, 0);
	int entryPoint = static_cast<int>(bytecode.instructions.size());
	bytecode.functionEntries[funcDecl->name] = entryPoint;
	bytecode.functionParamCounts[funcDecl->name] = static_cast<int>(funcDecl->params.size());
	std::vector<std::string> paramTypeNames;
	std::vector<std::vector<int>> paramArrayDims; 
	paramTypeNames.reserve(funcDecl->params.size());
	paramArrayDims.reserve(funcDecl->params.size()); 
	for (const auto &p : funcDecl->params)
	{
		paramTypeNames.push_back(p.type ? p.type->name : "any");
		paramArrayDims.push_back(p.type ? p.type->arrayDimensions : std::vector<int>{}); 
	}
	bytecode.functionParamTypeNames[funcDecl->name] = std::move(paramTypeNames);
	bytecode.functionParamArrayDims[funcDecl->name] = std::move(paramArrayDims); 
	std::string prevReturnType = currentFunctionReturnType;
	std::vector<int> prevReturnDims = currentFunctionReturnDims;
	bool prevHasReturn = currentFunctionHasReturn;
	currentFunctionReturnType = (funcDecl->returnType ? funcDecl->returnType->name : "any");
	currentFunctionReturnDims = (funcDecl->returnType ? funcDecl->returnType->arrayDimensions : std::vector<int>{});
	currentFunctionHasReturn = false;
	bytecode.functionReturnTypeNames[funcDecl->name] = currentFunctionReturnType;
	bytecode.functionReturnArrayDims[funcDecl->name] = currentFunctionReturnDims;
	bytecode.emit(OpCode::POP);
	for (const auto & param : std::ranges::reverse_view(funcDecl->params))
	{
		int varIndex = bytecode.getOrCreateVar(param.name);
		bytecode.emit(OpCode::STORE_VAR, varIndex);
		if (param.type && param.type->name != "any")
		{
			bool isArrayParam = !param.type->arrayDimensions.empty();
			if (isArrayParam)
			{
				arrayBaseTypes[param.name] = param.type->name;
				arrayDimensions[param.name] = param.type->arrayDimensions; 
				inferredTypes[param.name]  = ValueType::Array;
			} else {
				inferredTypes[param.name] = mapTypeNameToValueType(param.type->name);
			}
		}
	}
	generateBlockStmt(funcDecl->body.get());
	if (!currentFunctionHasReturn)
	{
		if (!currentFunctionReturnType.empty() &&
		    currentFunctionReturnType != "any"  &&
		    currentFunctionReturnType != "void")
		{
			throw std::runtime_error("Function '" + funcDecl->name + "' is declared to return '"
			          + currentFunctionReturnType + "' but has no return statement.\n");
		}
	}
	if (bytecode.instructions.empty() || bytecode.instructions.back().op != OpCode::RETURN)
	{
		bytecode.emit(OpCode::NULL_VAL);
		bytecode.emit(OpCode::RETURN);
	}
	currentFunctionReturnType = prevReturnType;
	currentFunctionReturnDims = prevReturnDims;
	currentFunctionHasReturn = prevHasReturn;
	bytecode.instructions[jumpOverIndex].operand1 = static_cast<int>(bytecode.instructions.size());
}
void CodeGenerator::generateBooleanExpr(const AST::BooleanExpr *boolExpr)
{
	if (boolExpr->value)
	{
		bytecode.emit(OpCode::TRUE_P);
	} else {
		bytecode.emit(OpCode::FALSE_P);
	}
}
void CodeGenerator::generateNullExpr(const AST::NullExpr *)
{
	bytecode.emit(OpCode::NULL_VAL);
}
void CodeGenerator::generateAssignmentExpr(const AST::AssignmentExpr *assignExpr)
{
    if (const auto *identExpr = dynamic_cast<const AST::IdentifierExpr *>(assignExpr->target.get()))
    {
        auto declIt = declaredTypes.find(identExpr->name);
        bool isAny = (declIt == declaredTypes.end() || declIt->second == "any");
        auto arrayIt = arrayBaseTypes.find(identExpr->name);
        bool isArrayTarget = (arrayIt != arrayBaseTypes.end());
        bool knownValType = false;
        ValueType valType = inferExpressionType(assignExpr->value.get(), knownValType);
        if (!isAny)
        {
            if (isArrayTarget)
            {
                if (knownValType && valType != ValueType::Array)
				{
                    throw std::runtime_error("Type mismatch: cannot assign non-array to array variable '" + identExpr->name + "'");
                }
                std::string expectedBaseType = arrayIt->second;
				if (expectedBaseType != "any")
				{
					if (const auto *arrayLit = dynamic_cast<const AST::ArrayLiteralExpr *>(assignExpr->value.get()))
					{
						auto dimsIt = arrayDimensions.find(identExpr->name);
						if (dimsIt != arrayDimensions.end() && !dimsIt->second.empty() && dimsIt->second[0] != -1)
						{
							if (arrayLit->elements.size() != static_cast<size_t>(dimsIt->second[0]))
							{
								throw std::runtime_error("Array bounds error: assigning " + std::to_string(arrayLit->elements.size()) +
								                         " elements to array '" + identExpr->name + "' of size " + std::to_string(dimsIt->second[0]));
							}
						}
						bool isMultiDim = (dimsIt != arrayDimensions.end() && dimsIt->second.size() > 1);
						ValueType expectedElemType = isMultiDim
							? ValueType::Array
							: mapTypeNameToValueType(expectedBaseType);
						for (size_t i = 0; i < arrayLit->elements.size(); ++i)
						{
							bool elemKnown = false;
							ValueType elemType = inferExpressionType(arrayLit->elements[i].get(), elemKnown);
							if (elemKnown && elemType != expectedElemType)
							{
								throw std::runtime_error("Type mismatch in array assignment: element at index " +
								                         std::to_string(i) + " does not match expected base type '" +
								                         expectedBaseType + "'.");
							}
						}
					}
				}
            }
            else
            {
                if (knownValType && valType == ValueType::Array)
				{
                    throw std::runtime_error("Type mismatch: cannot assign array to scalar variable '" + identExpr->name + "'");
                }
                ValueType expectedType = mapTypeNameToValueType(declIt->second);
                if (knownValType && valType != expectedType && expectedType != ValueType::Null && expectedType != ValueType::Struct)
                {
                    throw std::runtime_error("Type mismatch: cannot assign value of mismatching type to variable '" + identExpr->name + "' of type '" + declIt->second + "'");
                }
            }
        }
        ValueType targetType = ValueType::Null;
        auto typeIt = inferredTypes.find(identExpr->name);
        if (typeIt != inferredTypes.end())
		{
            targetType = typeIt->second;
		}
        if (const auto *binExpr = dynamic_cast<const AST::BinaryExpr *>(assignExpr->value.get()))
        {
            generateBinaryExpr(binExpr, targetType);
        }
        else
        {
            generateExpression(assignExpr->value.get());
        }
        Value val;
        if (isLiteralExpression(assignExpr->value.get(), val))
        {
            inferredTypes[identExpr->name] = val.getType();
        }
        int varIndex = bytecode.getOrCreateVar(identExpr->name);
        bytecode.emit(OpCode::STORE_VAR, varIndex);
        bytecode.emit(OpCode::LOAD_VAR, varIndex);
    }
    else if (const auto *fieldExpr = dynamic_cast<const AST::FieldAccessExpr *>(assignExpr->target.get()))
    {
        generateExpression(fieldExpr->object.get());
        generateExpression(assignExpr->value.get());
        std::string tempName = "__assign_val_" + std::to_string(switchCounter++);
        int tempVar = bytecode.getOrCreateVar(tempName);
        bytecode.emit(OpCode::STORE_VAR, tempVar); 
        bytecode.emit(OpCode::LOAD_VAR, tempVar);  
        int fieldNameIndex = bytecode.addStringConstant(fieldExpr->fieldName);
        bytecode.emit(OpCode::SET_FIELD, fieldNameIndex);
        bytecode.emit(OpCode::POP); 
        bytecode.emit(OpCode::LOAD_VAR, tempVar); 
    }
    else if (const auto *arrayAccess = dynamic_cast<const AST::ArrayAccessExpr *>(assignExpr->target.get()))
    {
        if (const auto *identExpr = dynamic_cast<const AST::IdentifierExpr *>(arrayAccess->array.get()))
        {
            auto dimsIt = arrayDimensions.find(identExpr->name);
            if (dimsIt != arrayDimensions.end() && !dimsIt->second.empty() && dimsIt->second[0] != -1)
            {
                Value idxVal;
                if (isLiteralExpression(arrayAccess->index.get(), idxVal) && idxVal.isInt())
                {
                    i64 idx = idxVal.asInt();
                    if (idx < 0 || idx >= dimsIt->second[0])
                    {
                        throw std::runtime_error("Compile-time bounds error: index " + std::to_string(idx) +
                                                 " is out of bounds for array '" + identExpr->name +
                                                 "' of size " + std::to_string(dimsIt->second[0]));
                    }
                }
            }
            auto arrayIt = arrayBaseTypes.find(identExpr->name);
            if (arrayIt != arrayBaseTypes.end())
            {
                std::string expectedBaseType = arrayIt->second;
                if (expectedBaseType != "any")
                {
                    ValueType expectedElemType = mapTypeNameToValueType(expectedBaseType);
                    bool      known = false;
                    ValueType valType = inferExpressionType(assignExpr->value.get(), known);
                    if (known && valType != expectedElemType)
                    {
                        throw std::runtime_error("Type mismatch: cannot assign value of mismatching type to array element of type '" +
                                                 expectedBaseType + "'.");
                    }
                }
            }
        }
        generateExpression(arrayAccess->array.get());
        generateExpression(arrayAccess->index.get());
        generateExpression(assignExpr->value.get());
        bytecode.emit(OpCode::STORE_ARR);
    }
    else
    {
        throw std::runtime_error("Invalid assignment target.");
    }
}
void CodeGenerator::generateStructInstanceExpr(const AST::StructInstanceExpr *expr)
{
	auto it = bytecode.structEntries.find(expr->structName);
	if (it != bytecode.structEntries.end())
	{
		int structIndex = it->second;
		bytecode.emit(OpCode::NEW_STRUCT_INSTANCE_STATIC, structIndex);
		for (const auto &[fieldName, fieldValue] : expr->fieldValues)
		{
			generateExpression(fieldValue.get());
			int fieldNameIndex = bytecode.addStringConstant(fieldName);
			bytecode.emit(OpCode::SET_FIELD, fieldNameIndex);
		}
	} else {
		int structNameIndex = bytecode.addStringConstant(expr->structName);
		bytecode.emit(OpCode::NEW_STRUCT, structNameIndex);
		for (const auto &[fieldName, fieldValue] : expr->fieldValues)
		{
			generateExpression(fieldValue.get());
			int fieldNameIndex = bytecode.addStringConstant(fieldName);
			bytecode.emit(OpCode::SET_FIELD, fieldNameIndex);
		}
	}
}
void CodeGenerator::generateFieldAccessExpr(const AST::FieldAccessExpr *expr)
{
	generateExpression(expr->object.get());
	int fieldNameIndex = bytecode.addStringConstant(expr->fieldName);
	bytecode.emit(OpCode::GET_FIELD, fieldNameIndex);
}
void CodeGenerator::generatePostfixExpr(const AST::PostfixExpr *expr, bool resultNeeded)
{
    const auto *identExpr = dynamic_cast<const AST::IdentifierExpr *>(expr->operand.get());
    if (identExpr == nullptr)
	{
        throw std::runtime_error("Postfix operators only supported on variables");
	}
    int varIndex = bytecode.getOrCreateVar(identExpr->name);
    if (resultNeeded)
	{
        bytecode.emit(OpCode::LOAD_VAR, varIndex);
	}
    bytecode.emit(OpCode::LOAD_VAR, varIndex);
    int oneIndex = bytecode.addConstant(Value(static_cast<i64>(1)));
    bytecode.emit(OpCode::PUSH_CONST, oneIndex);
    auto it = inferredTypes.find(identExpr->name);
    bool varIsInt = (it != inferredTypes.end() && it->second == ValueType::Int);
    if (expr->op == AST::PostfixOp::Increment)
	{
        bytecode.emit(varIsInt ? OpCode::IADD : OpCode::FLADD);
    } else {
        bytecode.emit(varIsInt ? OpCode::ISUBTRACT : OpCode::FLSUBTRACT);
	}
    bytecode.emit(OpCode::STORE_VAR, varIndex);
}
void CodeGenerator::generateStructDecl(const AST::StructDecl *decl)
{
	std::string structDef = "struct " + decl->name + " {";
	for (const auto &field : decl->fields)
	{
		structDef += " " + field.name + ":" + field.type->name + ",";
	}
	if (!decl->fields.empty())
	{
		structDef.pop_back();
	}
	structDef += " }";
	bytecode.addConstant(Value(structDef));
	int firstConstIndex = static_cast<int>(bytecode.constants.size());
	for (const auto &field : decl->fields)
	{
		(void)field;
		bytecode.addConstant(Value());
	}
	StructInfo info;
	info.name = decl->name;
	info.firstConstIndex = firstConstIndex;
	info.fieldCount = static_cast<int>(decl->fields.size());
	for (const auto &field : decl->fields)
	{
		info.fieldNames.push_back(field.name);
		info.fieldArrayDims.push_back(field.type->arrayDimensions);
		info.fieldTypeNames.push_back(field.type->name);
	}
	if (!bytecode.structEntries.contains(decl->name))
	{
		int index = static_cast<int>(bytecode.structs.size());
		bytecode.structs.push_back(std::move(info));
		bytecode.structEntries[decl->name] = index;
	}
}
void CodeGenerator::generateSwitchStmt(const AST::SwitchStmt *switchStmt)
{
	generateExpression(switchStmt->expr.get());
	std::string tempName = "__switch_" + std::to_string(switchCounter++);
	int         tempVarIndex = bytecode.getOrCreateVar(tempName);
	bytecode.emit(OpCode::STORE_VAR, tempVarIndex);
	bool known = false;
	ValueType inferred = inferExpressionType(switchStmt->expr.get(), known);
	if (known)
	{
		inferredTypes[tempName] = inferred;
	}
	std::vector<int> endJumps; 
	for (const auto &caseClause : switchStmt->cases)
	{
		bytecode.emit(OpCode::LOAD_VAR, tempVarIndex);
		generateExpression(caseClause.value.get());
		bytecode.emit(OpCode::FLEQUAL);
		int skipJump = static_cast<int>(bytecode.instructions.size());
		bytecode.emit(OpCode::JUMP_IF_FALSE, 0); 
		for (const auto &stmt : caseClause.statements)
		{
			generateStatement(stmt.get());
		}
		int endJump = static_cast<int>(bytecode.instructions.size());
		bytecode.emit(OpCode::JUMP, 0); 
		endJumps.push_back(endJump);
		bytecode.instructions[skipJump].operand1 = static_cast<int>(bytecode.instructions.size());
	}
	for (const auto &stmt : switchStmt->defaultStmts)
	{
		generateStatement(stmt.get());
	}
	int endIndex = static_cast<int>(bytecode.instructions.size());
	for (int jumpIdx : endJumps)
	{
		bytecode.instructions[jumpIdx].operand1 = endIndex;
	}
}
void CodeGenerator::generateArrayLiteralExpr(const AST::ArrayLiteralExpr *arrayLit, bool resultNeeded)
{
    for (const auto &elem : arrayLit->elements)
	{
        generateExpression(elem.get());
	}
    int count = static_cast<int>(arrayLit->elements.size());
    int countIdx = bytecode.addConstant(Value(static_cast<i64>(count)));
    bytecode.emit(OpCode::PUSH_CONST, countIdx);
    bytecode.emit(OpCode::NEW_ARR);
    if (!resultNeeded)
	{
        bytecode.emit(OpCode::POP);
	}
}
void CodeGenerator::generateArrayAccessExpr(const AST::ArrayAccessExpr *arrayAccess, bool resultNeeded)
{
    if (const auto *identExpr = dynamic_cast<const AST::IdentifierExpr *>(arrayAccess->array.get()))
	{
        auto dimsIt = arrayDimensions.find(identExpr->name);
        if (dimsIt != arrayDimensions.end() && !dimsIt->second.empty() && dimsIt->second[0] != -1)
		{
            Value idxVal;
            if (isLiteralExpression(arrayAccess->index.get(), idxVal) && idxVal.isInt())
			{
                i64 idx = idxVal.asInt();
                if (idx < 0 || idx >= dimsIt->second[0])
				{
                    throw std::runtime_error("Compile-time bounds error: index " + std::to_string(idx) +
                                             " is out of bounds for array '" + identExpr->name +
                                             "' of size " + std::to_string(dimsIt->second[0]));
                }
            }
        }
    }
    else if (const auto *fieldExpr = dynamic_cast<const AST::FieldAccessExpr *>(arrayAccess->array.get()))
    {
        if (const auto *objIdent = dynamic_cast<const AST::IdentifierExpr *>(fieldExpr->object.get()))
        {
            std::string structName;
            auto declIt = declaredTypes.find(objIdent->name);
            if (declIt != declaredTypes.end())
            {
                structName = declIt->second;
            }
            for (const auto &s : bytecode.structs)
            {
                if (!structName.empty() && s.name != structName)
				{
                    continue;
				}
                for (size_t i = 0; i < s.fieldNames.size(); ++i)
                {
                    if (s.fieldNames[i] == fieldExpr->fieldName)
                    {
                        const auto &dims = s.fieldArrayDims[i];
                        if (!dims.empty() && dims[0] != -1)
                        {
                            Value idxVal;
                            if (isLiteralExpression(arrayAccess->index.get(), idxVal) && idxVal.isInt())
                            {
                                i64 idx = idxVal.asInt();
                                if (idx < 0 || idx >= dims[0])
                                {
                                    throw std::runtime_error("Compile-time bounds error: index " + std::to_string(idx) +
                                                             " is out of bounds for field array '" + fieldExpr->fieldName +
                                                             "' of size " + std::to_string(dims[0]));
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    bool isStructAccess = false;
    if (const auto *identExpr = dynamic_cast<const AST::IdentifierExpr *>(arrayAccess->array.get()))
    {
        auto it = inferredTypes.find(identExpr->name);
        if (it != inferredTypes.end() && it->second == ValueType::Struct)
		{
            isStructAccess = true;
		}
    }
    generateExpression(arrayAccess->array.get());
    generateExpression(arrayAccess->index.get());
    bytecode.emit(isStructAccess ? OpCode::GET_FIELD_DYN : OpCode::LOAD_ARR);
    if (!resultNeeded)
	{
        bytecode.emit(OpCode::POP);
	}
}
ValueType CodeGenerator::mapTypeNameToValueType(const std::string &typeName)
{
    if (typeName == "int" || typeName == "i64")
	{
		return ValueType::Int;
	}
    if (typeName == "float" || typeName == "f64")
	{
		return ValueType::Float;
	}
    if (typeName == "string")
	{
		return ValueType::String;
	}
    if (typeName == "bool")
	{
		return ValueType::Bool;
	}
    if (typeName == "struct")
	{ [[unlikely]]
		return ValueType::Struct;
	}
    if (bytecode.structEntries.contains(typeName))
    { [[likely]] 
		return ValueType::Struct;
	}
    if (typeName == "void")
	{
		return ValueType::Null;
	}
    if (typeName == "any")
	{
		return ValueType::Null;
	}
    throw std::runtime_error("Unknown type name '" + typeName +
                              "' (if this is a struct, make sure it is declared before its first use).");
}
void CodeGenerator::generateDefaultArray(const std::vector<int> &dims, size_t dimIdx, const std::string &baseTypeName)
{
	if (dimIdx >= dims.size())
	{
		return;
	}
	int count = dims[dimIdx];
	count = std::max(count, 0);
	if (dimIdx == dims.size() - 1)
	{
		Value defaultValue;
		if (baseTypeName == "int" || baseTypeName == "i64")
		{
			defaultValue = Value(static_cast<i64>(0));
		} else if (baseTypeName == "float" || baseTypeName == "f64") {
			defaultValue = Value(0.0);
		} else if (baseTypeName == "string") {
			defaultValue = Value(std::string(""));
		} else if (baseTypeName == "bool") {
			defaultValue = Value(false);
		} else {
			defaultValue = Value();
		}
		for (int i = 0; i < count; ++i)
		{
			int constIdx = bytecode.addConstant(defaultValue);
			bytecode.emit(OpCode::PUSH_CONST, constIdx);
		}
	} else {
		for (int i = 0; i < count; ++i)
		{
			generateDefaultArray(dims, dimIdx + 1, baseTypeName);
		}
	}
	int countIdx = bytecode.addConstant(Value(static_cast<i64>(count)));
	bytecode.emit(OpCode::PUSH_CONST, countIdx);
	bytecode.emit(OpCode::NEW_ARR);
}
} // namespace Phasor#pragma once
#include "../AST/AST.hpp"
#ifndef CMAKE_PCH
#include <Value.hpp>
#endif
#include <phsint.hpp>
#include <map>
#include <unordered_set>
#include <string>
#include <vector>
#include <optional>
#include <platform.h>
#include "Bytecode.hpp"
namespace Phasor
{
/**
 * @brief Code generator for Phasor VM
 */
class CodeGenerator
{
  public:
	/**
	 * @brief Generate bytecode from program
	 *
	 * @param program Program to generate bytecode for
	 * @param existingVars Existing variables to use
	 * @param nextVarIdx Next available variable index
	 * @param replMode REPL mode
	 * @return Bytecode Generated bytecode
	 */
	Bytecode generate(const AST::Program &program, const std::unordered_map<std::string, int> &existingVars = {},
	                  int nextVarIdx = 0, bool replMode = false);
  private:
	Bytecode bytecode;       ///< Generated bytecode
	bool     isRepl = false; ///< REPL mode
	/// @brief Functions that survive dead-code elimination (empty = DCE not yet run).
	std::unordered_set<std::string> liveFunctions;
	// Inferred types for variables (simple, flow-insensitive mapping)
	std::unordered_map<std::string, ValueType> inferredTypes;
	std::unordered_map<std::string, std::unordered_map<std::string, ValueType>> inferredFieldTypes;
	std::unordered_map<std::string, std::string> declaredTypes;
	std::string currentFunctionReturnType;
	std::vector<int> currentFunctionReturnDims;
	bool currentFunctionHasReturn = false;
	std::unordered_map<std::string, std::vector<int>> arrayDimensions;
	std::unordered_map<std::string, std::string> arrayBaseTypes;
	std::unordered_set<std::string> forwardDecls;
	// Register allocation for v2.0
	u8           nextRegister = 0; ///< Next available register
	std::vector<bool> registerInUse;    ///< Track which registers are in use
	struct ScopeFrame {
		std::vector<std::pair<int, std::string>>                    declaredIndices;
		std::unordered_map<std::string, int>                        savedBindings;
		std::unordered_map<std::string, std::optional<ValueType>>   savedInferredTypes;
		std::unordered_map<std::string, std::optional<std::string>> savedArrayBaseTypes;
		std::unordered_map<std::string, std::optional<std::vector<int>>> savedArrayDimensions;
		std::unordered_map<std::string, std::optional<std::string>> savedDeclaredTypes;
	};
	std::vector<ScopeFrame> scopeStack;
	/// @brief Allocate a new register
	u8 allocateRegister()
	{
		for (size_t i = 0; i < MAX_REGISTERS; i++)
		{
			if (i >= registerInUse.size())
			{
				registerInUse.resize(i + 1, false);
			}
			if (!registerInUse[i])
			{
				registerInUse[i] = true;
				return static_cast<u8>(i);
			}
		}
		throw std::runtime_error("Out of registers");
	}
	/// @brief Free a register
	void freeRegister(u8 reg)
	{
		if (reg < registerInUse.size())
		{
			registerInUse[reg] = false;
		}
	}
	/// @brief Reset register allocator
	void resetRegisters()
	{
		registerInUse.clear();
		nextRegister = 0;
	}
	/// @brief Check if expression is a compile-time literal
	static bool isLiteralExpression(const AST::Expression *expr, Value &outValue);
	/// @brief Simple expression type inference (conservative)
	/// @param expr expression to inspect
	/// @param known set to true when a type is known
	/// @return inferred ValueType (valid only when known == true)
	ValueType inferExpressionType(const AST::Expression *expr, bool &known);
	void generateStatement(const AST::Statement *stmt);                          ///< Generate bytecode from Statement
	void generateExpression(const AST::Expression *expr, bool resultNeeded = true); ///< Generate bytecode from Expression
	void generateVarDecl(const AST::VarDecl *varDecl);                 ///< Generate bytecode from Variable Declaration
	void generateExpressionStmt(const AST::ExpressionStmt *exprStmt);  ///< Generate bytecode from Expression Statement
	void generatePrintStmt(const AST::PrintStmt *printStmt);           ///< Generate bytecode from Print Statement
	void generateImportStmt(const AST::ImportStmt *importStmt);        ///< Generate bytecode from Import Statement
	void generateExportStmt(const AST::ExportStmt *exportStmt);        ///< Generate bytecode from Export Statement
	void generateNumberExpr(const AST::NumberExpr *numExpr);           ///< Generate bytecode from Numeral Expression
	void generateStringExpr(const AST::StringExpr *strExpr);           ///< Generate bytecode from String Expression
	void generateIdentifierExpr(const AST::IdentifierExpr *identExpr); ///< Generate bytecode from Identifier Expression
	void generateUnaryExpr(const AST::UnaryExpr *unaryExpr);           ///< Generate bytecode from Unary Expression
	void generateCallExpr(const AST::CallExpr *callExpr);              ///< Generate bytecode from Call Expression
	void generateBinaryExpr(const AST::BinaryExpr *binExpr, ValueType hint = ValueType::Null);           ///< Generate bytecode from Binary Expression
	void generateBlockStmt(const AST::BlockStmt *blockStmt);           ///< Generate bytecode from Block Statement
	void generateIfStmt(const AST::IfStmt *ifStmt);                    ///< Generate bytecode from If Statement
	void generateWhileStmt(const AST::WhileStmt *whileStmt);           ///< Generate bytecode from While Statement
	void generateForStmt(const AST::ForStmt *forStmt);                 ///< Generate bytecode from For Statement
	void generateReturnStmt(const AST::ReturnStmt *returnStmt);        ///< Generate bytecode from Return Statement
	void generateUnsafeBlockStmt(
	    const AST::UnsafeBlockStmt *unsafeStmt);                  ///< Generate bytecode from Unsafe Block Statement
	void generateFunctionDecl(const AST::FunctionDecl *funcDecl); ///< Generate bytecode from Function Declaration
	void generateBooleanExpr(const AST::BooleanExpr *boolExpr);   ///< Generate bytecode from Boolean Expression
	void generateNullExpr(const AST::NullExpr *nullExpr);         ///< Generate bytecode from Null Expression
	void generateAssignmentExpr(
	    const AST::AssignmentExpr *assignExpr); ///< Generate bytecode from Assignment Expression
	void generateStructDecl(const AST::StructDecl *decl);
	void generateStructInstanceExpr(const AST::StructInstanceExpr *expr);
	void generateFieldAccessExpr(const AST::FieldAccessExpr *expr);
	void generatePostfixExpr(const AST::PostfixExpr *expr, bool resultNeeded = true);
	void generateBreakStmt();
	void generateContinueStmt();
	void generateSwitchStmt(const AST::SwitchStmt *switchStmt);
	void generateDefaultArray(const std::vector<int> &dims, size_t dimIdx, const std::string &baseTypeName);
	void generateArrayLiteralExpr(const AST::ArrayLiteralExpr *arrayLit, bool resultNeeded);
	void generateArrayAccessExpr(const AST::ArrayAccessExpr *arrayAccess, bool resultNeeded);
	ValueType mapTypeNameToValueType(const std::string &typeName);
	// Loop context for break/continue
	std::vector<int>              loopStartStack;     // Stack of loop start positions
	std::vector<std::vector<int>> breakJumpsStack;    // Stack of break jump positions to patch
	std::vector<std::vector<int>> continueJumpsStack; // Stack of continue jump positions to patch
	int switchCounter = 0; // Monotonic counter for unique switch temp variable names
};
} // namespace Phasorset(CODEGEN_SOURCES
    ${CMAKE_CURRENT_SOURCE_DIR}/CodeGen.cpp
    ${CMAKE_CURRENT_SOURCE_DIR}/Bytecode/BytecodeSerializer.cpp
    ${CMAKE_CURRENT_SOURCE_DIR}/Bytecode/BytecodeDeserializer.cpp
    ${CMAKE_CURRENT_SOURCE_DIR}/IR/PhasorIR.cpp
    ${CMAKE_CURRENT_SOURCE_DIR}/../ISA/map.cpp
    ${CMAKE_CURRENT_SOURCE_DIR}/C/CCodeGenerator.cpp
)

set(CODEGEN_HEADERS
    ${CMAKE_CURRENT_SOURCE_DIR}/CodeGen.hpp
    ${CMAKE_CURRENT_SOURCE_DIR}/Bytecode.hpp
    ${CMAKE_CURRENT_SOURCE_DIR}/Bytecode/BytecodeSerializer.hpp
    ${CMAKE_CURRENT_SOURCE_DIR}/Bytecode/BytecodeDeserializer.hpp
    ${CMAKE_CURRENT_SOURCE_DIR}/IR/PhasorIR.hpp
    ${CMAKE_CURRENT_SOURCE_DIR}/C/CCodeGenerator.hpp
    ${CMAKE_SOURCE_DIR}/src/AST/AST.hpp
)

add_library(PhasorCodegen STATIC ${CODEGEN_SOURCES} ${CODEGEN_HEADERS})

target_link_libraries(PhasorCodegen PUBLIC "$<$<PLATFORM_ID:Darwin>:-framework CoreFoundation>" "$<$<PLATFORM_ID:Darwin>:-framework Security>")`CodeGen.hpp/.cpp` - Code generator. Walks the AST and emits Instruction objects into a Bytecode struct (constant pool, variable map, function entries, struct metadata). Does constant folding on literal binary expressions and basic type inference to pick integer vs. float opcodes. Uses a small register allocator for binary expressions, with loop context stacks for break/continue jump patching.

`Bytecode/` - Binary `.phsb` serializer/deserializer. 4-section layout: constants → variables → functions → instructions, with a CRC32 integrity check in the header. Also has a python module in `../Extensions`.

`IR/` — Assembly `.phir` serializer/deserializer. Includes inline comments in the output (e.g. ; var=x, ; const[0]="hello").

`Cpp/` — Generates a C++ header with the bytecode embedded as a `constexpr unsigned char[]`, placed in a named executable section (.phsb). Used by the native compiler output and is also supported by the bytecode Python module.
